import { useState, useRef, useCallback, useEffect } from 'react';
import {
  type ReceiptData, type BrandingSettings, type SavedReceipt, type TextElementId,
  DEFAULT_DATA, todayString, newLineItem, normalizeData, computeTotals, lineAmount, parseNum, money, loadDesign, saveDesign,
} from './types';
import { loadReceipts, saveReceipts, generateId, validate } from './utils';
import { captureReceiptPng, captureReceiptPdf, printReceipt, renderReceiptPdf } from './exporters';
import EmailDialog from './components/EmailDialog';
import EmailSettings from './components/EmailSettings';
import EditorCanvas from './components/EditorCanvas';
import GuideToolbar from './components/GuideToolbar';
import { type GuideSettings, type AlignOp, loadGuides, saveGuides, alignSelection, measureElements, getPos, setPositions } from './alignment';
import ReceiptForm from './components/ReceiptForm';
import DesignPanel, { type DesignElement } from './components/DesignPanel';
import CompanyPanel from './components/CompanyPanel';
import TypographyPanel from './components/TypographyPanel';
import ReceiptHistory from './components/ReceiptHistory';
import { Button } from '@project/components/ui/button';
import { Toaster } from '@project/components/ui/sonner';
import { cn } from '@project/components/lib/utils';
import { toast } from 'sonner';
import { FilePlus, Printer, FileImage, FileDown, FileText, Palette, Building2, Type, History, ReceiptText, Menu, Mail } from 'lucide-react';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from '@project/components/ui/sheet';
import PreviewPane from './components/PreviewPane';
import { issueReceiptNumber } from 'zitejs/api';

const TABS = [
  { id: 'create', label: 'Create', icon: FileText },
  { id: 'design', label: 'Design', icon: Palette },
  { id: 'company', label: 'Header', icon: Building2 },
  { id: 'typography', label: 'Text', icon: Type },
  { id: 'history', label: 'History', icon: History },
  { id: 'email', label: 'Email', icon: Mail },
] as const;
type Tab = typeof TABS[number]['id'];
const TAB_TITLES: Record<Tab, string> = { create: 'Create Receipt', design: 'Logo & Watermark', company: 'Header', typography: 'Text Styles', history: 'Receipt History', email: 'Email Settings' };

function emptyData(): ReceiptData {
  return { items: [newLineItem()], accountName: '', accountNumber: '', address: '', plan: '', generatedBy: '', receiptNumber: '', date: todayString() };
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => ({ ...DEFAULT_DATA, receiptNumber: '' }));
  const [savedDesign, setSavedDesign] = useState<BrandingSettings>(() => loadDesign());
  const [branding, setBranding] = useState<BrandingSettings>(savedDesign);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [tab, setTab] = useState<Tab>('create');
  const [receipts, setReceipts] = useState<SavedReceipt[]>(() => loadReceipts());
  const [editingId, setEditingId] = useState<string | null>(null);
  const [selectedElement, setSelectedElement] = useState<TextElementId | null>(null);
  const [designEl, setDesignEl] = useState<DesignElement>('logo');
  const [busy, setBusy] = useState<string | null>(null);
  const receiptRef = useRef<HTMLDivElement>(null);
  const [emailReceipt, setEmailReceipt] = useState<SavedReceipt | null>(null);
  const setEmailStatus = (id: string, status: 'Sent' | 'Failed') => { saveReceipts(loadReceipts().map(x => x.id === id ? { ...x, emailStatus: status } : x)); setReceipts(loadReceipts()); };

  const [selection, setSelection] = useState<string[]>([]);
  const [guides, setGuides] = useState<GuideSettings>(() => loadGuides());
  const updateGuides = (g: GuideSettings) => { setGuides(g); saveGuides(g); };

  const locked = editingId !== null;
  const designDirty = !locked && JSON.stringify(branding) !== JSON.stringify(savedDesign);

  // Alignment only touches the selected elements' positions — never fonts, text, or other elements.
  const handleAlign = (op: AlignOp) => {
    if (!receiptRef.current) return;
    const pos = alignSelection(op, selection.filter(i => i !== 'watermark'), measureElements(receiptRef.current), branding);
    if (Object.keys(pos).length) setBranding(setPositions(branding, pos));
  };

  const refreshReceipts = useCallback(() => { setReceipts(loadReceipts()); }, []);

  const handleGenerate = async () => {
    if (busy) return;
    const errs = validate(data);
    setErrors(errs);
    if (Object.keys(errs).length > 0) {
      const n = Object.keys(errs).length;
      toast.error(`${n} field${n > 1 ? 's need' : ' needs'} attention — see the messages under each field.`);
      // Move focus to the first invalid field once the error states have rendered.
      requestAnimationFrame(() => {
        const first = document.querySelector<HTMLElement>('aside [aria-invalid="true"]');
        first?.scrollIntoView({ block: 'center' });
        first?.focus({ preventScroll: true });
      });
      return;
    }
    const t = computeTotals(data.items);
    let receiptNumber: string;
    setBusy('generate');
    try {
      ({ receiptNumber } = await issueReceiptNumber({ accountName: data.accountName, total: t.total }));
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Could not issue a receipt number.');
      return;
    } finally { setBusy(null); }
    const issued = { ...data, receiptNumber };
    setData(issued);
    const entry: SavedReceipt = {
      id: generateId(),
      receiptNumber, date: data.date, accountName: data.accountName,
      accountNumber: data.accountNumber,
      transaction: data.items.map(i => i.description).join(', '),
      amount: money(t.total), generatedBy: data.generatedBy,
      lineItems: data.items.map((i, n) => ({ description: i.description, quantity: parseNum(i.quantity), unitPrice: parseNum(i.unitPrice), lineAmount: lineAmount(i), sortOrder: n })),
      subtotal: t.subtotal, lessAmount: t.less, total: t.total, paidBy: t.paidBy, paidTotal: t.paidTotal, changeAmount: t.change,
      emailStatus: 'Not Sent',
      data: issued, branding, savedAt: new Date().toISOString(),
    };
    saveReceipts([entry, ...loadReceipts()]);
    refreshReceipts();
    setEditingId(entry.id);
    toast.success(`Receipt #${receiptNumber} generated`);
  };

  const handleNew = () => { setData(emptyData()); setBranding(savedDesign); setEditingId(null); setErrors({}); setTab('create'); };

  const handleSaveDesign = () => { saveDesign(branding); setSavedDesign(branding); toast.success('Design saved — all receipts and exports now use it'); };

  const run = async (key: string, fn: () => Promise<void>, ok: string, fail: string) => {
    if (!receiptRef.current) return;
    setBusy(key);
    try { await fn(); if (ok) toast.success(ok); } catch (err) { toast.error(err instanceof Error && /cancelled|could not be loaded/.test(err.message) ? err.message : fail); console.error(err); } finally { setBusy(null); }
  };
  const name = `receipt-${data.receiptNumber || 'export'}`;
  const handlePrint = () => run('print', () => printReceipt(receiptRef.current!), '', 'Could not open print preview.');
  const handlePng = () => run('png', async () => dl(await captureReceiptPng(receiptRef.current!), `${name}.png`), 'PNG downloaded', 'PNG export failed. Please try again.');
  const handlePdf = () => run('pdf', () => captureReceiptPdf(receiptRef.current!, `${name}.pdf`), 'PDF downloaded', 'PDF export failed. Please try again.');

  const loadReceipt = (r: SavedReceipt) => { setData(normalizeData(r.data)); setBranding(r.branding); setEditingId(r.id); setTab('create'); };

  const selectDesign = (el: DesignElement) => { setDesignEl(el); setSelection([el]); };
  // Logo click opens its editor; the watermark pattern (hit on empty receipt area) only switches tabs when already designing.
  const onGraphicClick = (id: string) => {
    const el: DesignElement = id === 'logo' ? 'logo' : 'watermark';
    setDesignEl(el);
    if (el === 'logo' || tab === 'design') setTab('design');
  };

  const asideRef = useRef<HTMLElement>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const stacked = () => window.innerWidth < 1024;
  // In the stacked (tablet/phone) layout, jump back up to the panel the canvas just opened.
  const revealPanel = () => { if (stacked()) asideRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }); };
  const goTab = (t: Tab) => { setTab(t); setMenuOpen(false); revealPanel(); };

  // Keep the focused field visible above the on-screen keyboard.
  useEffect(() => {
    if (!window.matchMedia('(pointer: coarse)').matches) return;
    const onFocus = (e: FocusEvent) => {
      const el = e.target as HTMLElement;
      if (!el.matches('input, textarea, [contenteditable="true"]')) return;
      setTimeout(() => {
        const r = el.getBoundingClientRect();
        const vh = window.visualViewport?.height ?? window.innerHeight;
        if (r.top < 64 || r.bottom > vh - 80) el.scrollIntoView({ block: 'center', behavior: 'smooth' });
      }, 300);
    };
    document.addEventListener('focusin', onFocus);
    return () => document.removeEventListener('focusin', onFocus);
  }, []);

  // Keyboard: arrows nudge the selected element(s) 1px (Shift = 10px); Escape clears the selection.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement;
      if (!selection.length || t.closest('input, textarea, select, [role="slider"], [role="dialog"], [contenteditable="true"]')) return;
      if (e.key === 'Escape') { setSelection([]); return; }
      const d = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[e.key];
      if (!d) return;
      e.preventDefault();
      const k = e.shiftKey ? 10 : 1;
      setBranding(b => setPositions(b, Object.fromEntries(selection.map(id => { const p = getPos(b, id); return [id, { x: p.x + d[0] * k, y: p.y + d[1] * k }]; }))));
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [selection]);

  const later = (r: SavedReceipt, fn: (el: HTMLDivElement) => Promise<void> | void) => {
    loadReceipt(r);
    setTimeout(async () => { if (receiptRef.current) { try { await fn(receiptRef.current); } catch { toast.error('Export failed'); } } }, 500);
  };

  const exportButtons = (cls = '') => (
    <>
      <Button variant="outline" className={cn('gap-2', cls)} disabled={!!busy} onClick={handlePrint}><Printer className="h-4 w-4" />Print</Button>
      <Button variant="outline" className={cn('gap-2', cls)} disabled={!!busy} onClick={handlePdf}><FileDown className="h-4 w-4" />{busy === 'pdf' ? 'Preparing…' : 'PDF'}</Button>
      <Button variant="outline" className={cn('gap-2', cls)} disabled={!!busy} onClick={handlePng}><FileImage className="h-4 w-4" />{busy === 'png' ? 'Preparing…' : 'PNG'}</Button>
      {locked && <Button className={cn('gap-2', cls)} disabled={!!busy} onClick={() => { const r = receipts.find(x => x.id === editingId); if (r) setEmailReceipt(r); }}><Mail className="h-4 w-4" />Email</Button>}
    </>
  );

  return (
    <div className="flex min-h-[100dvh] flex-col bg-background lg:h-screen lg:min-h-0">
      <Toaster duration={6000} closeButton position="top-center" />
      <EmailDialog receipt={emailReceipt} onClose={() => setEmailReceipt(null)} onStatus={setEmailStatus}
        renderPdf={() => receiptRef.current ? renderReceiptPdf(receiptRef.current) : Promise.reject(new Error('Receipt not ready'))} />
      <header className="touch-ui sticky top-0 z-40 flex items-center justify-between gap-3 border-b bg-card px-3 py-2.5 sm:px-5 lg:static">
        <div className="flex min-w-0 items-center gap-3">
          <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-primary text-primary-foreground"><ReceiptText className="h-5 w-5" /></div>
          <div className="min-w-0">
            <h1 className="truncate text-base font-semibold leading-tight">Converge Receipt Maker</h1>
            <p className="truncate text-xs text-muted-foreground">{locked ? `Viewing #${data.receiptNumber}` : 'New collection receipt'}</p>
          </div>
        </div>
        <div className="hidden items-center gap-2 md:flex">
          <Button variant="secondary" className="gap-2" onClick={handleNew}><FilePlus className="h-4 w-4" />New receipt</Button>
          <div className="mx-1 h-6 w-px bg-border" />
          {exportButtons()}
        </div>
        <Sheet open={menuOpen} onOpenChange={setMenuOpen}>
          <SheetTrigger asChild>
            <Button variant="outline" size="icon" className="h-11 w-11 shrink-0 md:hidden" aria-label="Open navigation menu"><Menu className="h-5 w-5" /></Button>
          </SheetTrigger>
          <SheetContent side="right" className="touch-ui flex w-[85vw] max-w-xs flex-col gap-1 overflow-y-auto">
            <SheetHeader><SheetTitle>Menu</SheetTitle></SheetHeader>
            <Button className="mt-3 justify-start gap-2" onClick={() => { handleNew(); setMenuOpen(false); }}><FilePlus className="h-4 w-4" />New receipt</Button>
            <div className="my-2 h-px bg-border" />
            {TABS.map(t => (
              <Button key={t.id} variant={tab === t.id ? 'secondary' : 'ghost'} className="justify-start gap-3" onClick={() => goTab(t.id)}>
                <t.icon className="h-4 w-4" />{TAB_TITLES[t.id]}
              </Button>
            ))}
          </SheetContent>
        </Sheet>
      </header>

      <div className="flex flex-1 flex-col lg:min-h-0 lg:flex-row">
        <aside ref={asideRef} className="touch-ui flex w-full min-w-0 shrink-0 scroll-mt-16 flex-col bg-background lg:w-[420px] lg:border-r xl:w-[460px]">
          <nav aria-label="Sections" className="hidden grid-cols-6 gap-1 border-b bg-card p-2 md:grid">
            {TABS.map(t => (
              <button key={t.id} type="button" aria-current={tab === t.id ? 'page' : undefined} onClick={() => setTab(t.id)}
                className={cn('flex flex-col items-center gap-1 rounded-md py-2 text-xs font-medium transition-colors',
                  tab === t.id ? 'bg-accent text-accent-foreground font-semibold ring-1 ring-primary/40' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}>
                <t.icon className="h-4 w-4" />{t.label}
                {t.id === 'design' && designDirty && <span className="sr-only">(unsaved)</span>}
              </button>
            ))}
          </nav>
          <div className="grid grid-cols-2 gap-2 border-b bg-card p-2 md:hidden">
            {(['create', 'history'] as const).map(id => {
              const t = TABS.find(x => x.id === id)!;
              return (
                <button key={id} type="button" aria-current={tab === id ? 'page' : undefined} onClick={() => setTab(id)}
                  className={cn('flex h-11 items-center justify-center gap-2 rounded-md text-sm font-medium',
                    tab === id ? 'bg-accent text-accent-foreground font-semibold ring-1 ring-primary/40' : 'text-muted-foreground')}>
                  <t.icon className="h-4 w-4" />{TAB_TITLES[id]}
                </button>
              );
            })}
          </div>
          <div className="mx-auto w-full max-w-2xl px-4 pt-4 pb-0 lg:min-h-0 lg:max-w-none lg:flex-1 lg:overflow-y-auto">
            {tab === 'create' && <ReceiptForm data={data} onChange={d => { setData(d); setErrors({}); }} errors={errors} locked={locked} onGenerate={handleGenerate}
              onClear={() => { setData(emptyData()); setErrors({}); }} />}
            {tab === 'design' && <DesignPanel branding={branding} onChange={setBranding} element={designEl} onElementChange={selectDesign} dirty={designDirty} onSave={handleSaveDesign} />}
            {tab === 'company' && <CompanyPanel company={branding.company} onChange={company => setBranding({ ...branding, company })} />}
            {tab === 'typography' && <TypographyPanel branding={branding} onChange={setBranding} selectedElement={selectedElement} onSelectElement={id => { setSelectedElement(id); setSelection(id ? [id] : []); }} />}
            {tab === 'history' && (
              <ReceiptHistory
                receipts={receipts}
                onView={r => { loadReceipt(r); revealPanel(); }}
                onDuplicate={r => { setData({ ...normalizeData(r.data), receiptNumber: '' }); setBranding(savedDesign); setEditingId(null); setTab('create'); toast('Duplicated — a new receipt number is assigned when you generate'); }}
                onDelete={id => { saveReceipts(loadReceipts().filter(x => x.id !== id)); refreshReceipts(); toast.success('Receipt deleted'); }}
                onPrint={r => later(r, el => printReceipt(el))}
                onDownload={r => later(r, async el => dl(await captureReceiptPng(el), `receipt-${r.receiptNumber}.png`))}
                onPdf={r => later(r, el => captureReceiptPdf(el, `receipt-${r.receiptNumber}.pdf`))}
                onEmail={r => { loadReceipt(r); setTab('history'); setEmailReceipt(r); }}
                onClose={() => setTab('create')}
              />
            )}
            {tab === 'email' && <EmailSettings />}
            {tab !== 'create' && tab !== 'design' && <div className="h-4" />}
          </div>
        </aside>

        <main aria-label="Receipt preview" className="min-w-0 border-t bg-muted/60 lg:min-h-0 lg:flex-1 lg:overflow-auto lg:border-t-0">
          <div className="flex items-center justify-between border-b bg-card px-4 py-2 lg:hidden">
            <span className="text-sm font-semibold">Receipt preview</span>
          </div>
          {designDirty && (
            <div className="touch-ui flex flex-wrap items-center justify-between gap-2 border-b bg-accent px-4 py-2 text-sm text-accent-foreground">
              <span>You have unsaved design changes.</span>
              <div className="flex gap-2">
                <Button size="sm" variant="ghost" onClick={() => setBranding(savedDesign)}>Discard</Button>
                <Button size="sm" onClick={handleSaveDesign}>Save design</Button>
              </div>
            </div>
          )}
          <GuideToolbar settings={guides} onSettings={updateGuides} selection={selection}
            onClearSelection={() => setSelection([])} onAlign={handleAlign}
            position={selection.length === 1 ? getPos(branding, selection[0]) : null}
            onPosition={p => setBranding(setPositions(branding, { [selection[0]]: p }))} />
          <PreviewPane receiptRef={receiptRef}>
            {scale => (
              <EditorCanvas data={data} branding={branding} onBrandingChange={setBranding} receiptRef={receiptRef} scale={scale}
                selection={selection} onSelectionChange={setSelection} settings={guides}
                onTextClick={id => { setSelectedElement(id); setTab('typography'); revealPanel(); }}
                onGraphicClick={id => { onGraphicClick(id); if (id === 'logo' || tab === 'design') revealPanel(); }} />
            )}
          </PreviewPane>
          <div className={cn('touch-ui grid gap-2 border-t bg-card p-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] md:hidden', locked ? 'grid-cols-4' : 'grid-cols-3')}>
            {exportButtons('w-full')}
          </div>
        </main>
      </div>
    </div>
  );
}

function dl(blob: Blob, name: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = name; a.click();
  URL.revokeObjectURL(url);
}

import { type BrandingSettings, type TextElementId, TEXT_ELEMENT_LABELS, RECEIPT_W, RECEIPT_H } from './types';

/* ─── Settings ─── */

export interface GuideSettings {
  showGrid: boolean;
  gridSize: number;
  snapToGrid: boolean;
  smartGuides: boolean;
  snapToElements: boolean;
  showMeasurements: boolean;
  snapDistance: number;
}

export const DEFAULT_GUIDES: GuideSettings = {
  showGrid: false, gridSize: 10, snapToGrid: false,
  smartGuides: true, snapToElements: true, showMeasurements: false, snapDistance: 6,
};

const GUIDE_KEY = 'converge-guide-settings';
export function loadGuides(): GuideSettings {
  try { return { ...DEFAULT_GUIDES, ...JSON.parse(localStorage.getItem(GUIDE_KEY) || '{}') }; } catch { return DEFAULT_GUIDES; }
}
export function saveGuides(g: GuideSettings) { localStorage.setItem(GUIDE_KEY, JSON.stringify(g)); }

/** Main receipt content boundaries (outer padding and the inner centered column). */
export const CONTENT = { left: 36, right: RECEIPT_W - 36, top: 12, bottom: RECEIPT_H - 14, innerLeft: 96, innerRight: RECEIPT_W - 86 };

/* ─── Geometry ─── */

export const isGraphic = (id: string) => id === 'logo' || id === 'watermark' || id.startsWith('wm:');

export interface Rect { x: number; y: number; w: number; h: number; text: boolean }
export type RectMap = Record<string, Rect>;

const union = (a: Rect, b: Rect): Rect => {
  const x = Math.min(a.x, b.x), y = Math.min(a.y, b.y);
  return { x, y, w: Math.max(a.x + a.w, b.x + b.w) - x, h: Math.max(a.y + a.h, b.y + b.h) - y, text: a.text };
};
export const unionAll = (rs: Rect[]) => rs.reduce(union);

export function elementLabel(id: string) {
  if (id === 'logo') return 'Logo';
  if (id === 'watermark') return 'Watermark Pattern';
  if (id.startsWith('wm:')) return 'Watermark';
  return TEXT_ELEMENT_LABELS[id as TextElementId] ?? id;
}

/** Measures every [data-el] element in receipt coordinates (unscaled px). */
export function measureElements(canvas: HTMLElement): RectMap {
  const c = canvas.getBoundingClientRect();
  const k = c.width / RECEIPT_W || 1;
  const out: RectMap = {};
  canvas.querySelectorAll<HTMLElement>('[data-el]').forEach(node => {
    const id = node.dataset.el!;
    const isText = !isGraphic(id);
    let r: DOMRect;
    if (isText) {
      const target = node.children.length === 1 ? node.children[0] : node;
      const range = document.createRange();
      range.selectNodeContents(target);
      r = range.getBoundingClientRect();
      if (!r.width) r = target.getBoundingClientRect();
    } else r = node.getBoundingClientRect();
    const rect: Rect = { x: (r.left - c.left) / k, y: (r.top - c.top) / k, w: r.width / k, h: r.height / k, text: isText };
    out[id] = out[id] ? union(out[id], rect) : rect;
  });
  return out;
}

export function hitTest(rects: RectMap, x: number, y: number): string | null {
  let best: string | null = null, area = Infinity;
  for (const [id, r] of Object.entries(rects)) {
    const pad = 2;
    if (x >= r.x - pad && x <= r.x + r.w + pad && y >= r.y - pad && y <= r.y + r.h + pad) {
      const a = id === 'watermark' ? 1e12 : r.w * r.h * (r.text ? 1 : 4); // text > images > pattern layer
      if (a < area) { area = a; best = id; }
    }
  }
  return best;
}

/* ─── Positions ─── */

export type Pos = { x: number; y: number };

export function getPos(b: BrandingSettings, id: string): Pos {
  if (id === 'logo') return { x: b.logo.x, y: b.logo.y };
  if (id === 'watermark') return { x: b.watermark.offsetX ?? 0, y: b.watermark.offsetY ?? 0 };
  if (id.startsWith('wm:')) {
    const it = b.watermark.customItems.find(c => c.id === id.slice(3));
    return { x: it?.x ?? 0, y: it?.y ?? 0 };
  }
  const t = b.textStyles[id as TextElementId];
  return { x: t?.offsetX ?? 0, y: t?.offsetY ?? 0 };
}

export function setPositions(b: BrandingSettings, pos: Record<string, Pos>): BrandingSettings {
  const next: BrandingSettings = { ...b, textStyles: { ...b.textStyles } };
  for (const [id, p] of Object.entries(pos)) {
    const x = Math.round(p.x), y = Math.round(p.y);
    if (id === 'logo') next.logo = { ...next.logo, x, y };
    else if (id === 'watermark') next.watermark = { ...next.watermark, offsetX: x, offsetY: y };
    else if (id.startsWith('wm:')) {
      const wid = id.slice(3);
      next.watermark = { ...next.watermark, customItems: next.watermark.customItems.map(c => c.id === wid ? { ...c, x, y } : c) };
    } else {
      const tid = id as TextElementId;
      next.textStyles[tid] = { ...next.textStyles[tid], offsetX: x, offsetY: y };
    }
  }
  return next;
}

export const isResizable = isGraphic;
export const isRotatable = isGraphic;

export function getSize(b: BrandingSettings, id: string) {
  if (id === 'logo') return { w: b.logo.width, h: b.logo.height };
  if (id === 'watermark') return { w: b.watermark.width, h: b.watermark.height };
  const it = b.watermark.customItems.find(c => c.id === id.slice(3));
  return { w: it?.width ?? 0, h: it?.height ?? 0 };
}

export function setSize(b: BrandingSettings, id: string, w: number, h: number): BrandingSettings {
  const width = Math.max(5, Math.round(w)), height = Math.max(5, Math.round(h));
  if (id === 'logo') return { ...b, logo: { ...b.logo, width, height } };
  if (id === 'watermark') return { ...b, watermark: { ...b.watermark, width, height } };
  const wid = id.slice(3);
  return { ...b, watermark: { ...b.watermark, customItems: b.watermark.customItems.map(c => c.id === wid ? { ...c, width, height } : c) } };
}

/* ─── Snapping & guides ─── */

export interface Guide { axis: 'x' | 'y'; pos: number; from: number; to: number }
export interface Measures {
  above?: { from: number; to: number; x: number };
  below?: { from: number; to: number; x: number };
  left: number; right: number; equal: boolean;
}
export interface LiveGuides { rect: Rect; guides: Guide[]; labels: string[]; measures?: Measures }

type Pt = { v: number; k: string };
type Target = Pt & { r?: Rect };

const xPts = (r: Rect): Pt[] => [{ v: r.x, k: 'left' }, { v: r.x + r.w / 2, k: 'cx' }, { v: r.x + r.w, k: 'right' }];
const yPts = (r: Rect): Pt[] => {
  const a = [{ v: r.y, k: 'top' }, { v: r.y + r.h / 2, k: 'cy' }, { v: r.y + r.h, k: 'bottom' }];
  if (r.text) a.push({ v: r.y + r.h * 0.8, k: 'base' });
  return a;
};

function targetsX(others: Rect[]): Target[] {
  return [
    ...others.flatMap(r => xPts(r).map(p => ({ ...p, r }))),
    { v: RECEIPT_W / 2, k: 'receipt' },
    { v: CONTENT.left, k: 'bound' }, { v: CONTENT.right, k: 'bound' },
    { v: CONTENT.innerLeft, k: 'bound' }, { v: CONTENT.innerRight, k: 'bound' },
  ];
}
function targetsY(others: Rect[]): Target[] {
  return [
    ...others.flatMap(r => yPts(r).map(p => ({ ...p, r }))),
    { v: RECEIPT_H / 2, k: 'receipt' },
    { v: CONTENT.top, k: 'bound' }, { v: CONTENT.bottom, k: 'bound' },
  ];
}

function compatible(pk: string, tk: string) {
  if (tk === 'bound') return pk === 'left' || pk === 'right' || pk === 'top' || pk === 'bottom';
  if (tk === 'receipt') return pk === 'cx' || pk === 'cy';
  return pk === tk;
}

function best(pts: Pt[], targets: Target[], th: number) {
  let res: { d: number } | null = null;
  for (const p of pts) for (const t of targets) {
    if (!compatible(p.k, t.k)) continue;
    const d = t.v - p.v;
    if (Math.abs(d) <= th && (!res || Math.abs(d) < Math.abs(res.d))) res = { d };
  }
  return res;
}

const moved = (r: Rect, dx: number, dy: number): Rect => ({ ...r, x: r.x + dx, y: r.y + dy });
const hOverlap = (a: Rect, b: Rect) => a.x < b.x + b.w && a.x + a.w > b.x;

function neighbours(F: Rect, others: Rect[]) {
  const col = others.filter(r => hOverlap(r, F));
  let above: Rect | undefined, below: Rect | undefined;
  for (const r of col) {
    if (r.y + r.h <= F.y + 0.5 && (!above || r.y + r.h > above.y + above.h)) above = r;
    if (r.y >= F.y + F.h - 0.5 && (!below || r.y < below.y)) below = r;
  }
  return { above, below };
}

export function computeMeasures(F: Rect, others: Rect[]): Measures {
  const { above, below } = neighbours(F, others);
  const cx = F.x + F.w / 2;
  const m: Measures = { left: F.x - CONTENT.left, right: CONTENT.right - (F.x + F.w), equal: false };
  if (above) m.above = { from: above.y + above.h, to: F.y, x: cx };
  if (below) m.below = { from: F.y + F.h, to: below.y, x: cx };
  if (m.above && m.below) m.equal = Math.abs((m.above.to - m.above.from) - (m.below.to - m.below.from)) < 1;
  return m;
}

const LABELS: Record<string, string> = {
  left: 'LEFT', right: 'RIGHT', cx: 'CENTER', top: 'TOP', bottom: 'BOTTOM', cy: 'SAME ROW', base: 'BASELINE',
};

export function detectGuides(F: Rect, others: Rect[]): { guides: Guide[]; labels: string[] } {
  const guides: Guide[] = [];
  const labels = new Set<string>();
  const tol = 1;
  for (const p of xPts(F)) for (const t of targetsX(others)) {
    if (!compatible(p.k, t.k) || Math.abs(t.v - p.v) > tol) continue;
    if (t.r) {
      guides.push({ axis: 'x', pos: t.v, from: Math.min(F.y, t.r.y), to: Math.max(F.y + F.h, t.r.y + t.r.h) });
      labels.add(LABELS[p.k]);
      if (!(t.r.y < F.y + F.h && t.r.y + t.r.h > F.y)) labels.add('SAME COLUMN');
    } else {
      guides.push({ axis: 'x', pos: t.v, from: 0, to: RECEIPT_H });
      labels.add(t.k === 'receipt' ? 'CENTER OF RECEIPT' : 'CONTENT EDGE');
    }
  }
  for (const p of yPts(F)) for (const t of targetsY(others)) {
    if (!compatible(p.k, t.k) || Math.abs(t.v - p.v) > tol) continue;
    if (t.r) {
      guides.push({ axis: 'y', pos: t.v, from: Math.min(F.x, t.r.x), to: Math.max(F.x + F.w, t.r.x + t.r.w) });
      labels.add(LABELS[p.k]);
    } else {
      guides.push({ axis: 'y', pos: t.v, from: 0, to: RECEIPT_W });
      labels.add(t.k === 'receipt' ? 'MIDDLE OF RECEIPT' : 'CONTENT EDGE');
    }
  }
  return { guides, labels: [...labels] };
}

function finish(F: Rect, others: Rect[], s: GuideSettings): LiveGuides {
  const g = s.smartGuides ? detectGuides(F, others) : { guides: [], labels: [] };
  const measures = s.showMeasurements ? computeMeasures(F, others) : undefined;
  if (measures?.equal) g.labels.push('EQUAL SPACING');
  return { rect: F, ...g, measures };
}

export function computeMove(start: Rect, rawDx: number, rawDy: number, others: Rect[], s: GuideSettings) {
  let dx = rawDx, dy = rawDy, sx = false, sy = false;
  const P = moved(start, dx, dy);
  if (s.snapToElements) {
    const bx = best(xPts(P), targetsX(others), s.snapDistance);
    if (bx) { dx += bx.d; sx = true; }
    const by = best(yPts(P), targetsY(others), s.snapDistance);
    if (by) { dy += by.d; sy = true; }
    if (!sy) {
      const { above, below } = neighbours(P, others);
      if (above && below) {
        const gap = (below.y - (above.y + above.h) - P.h) / 2;
        const d = above.y + above.h + gap - P.y;
        if (Math.abs(d) <= s.snapDistance) { dy += d; sy = true; }
      }
    }
  }
  if (s.snapToGrid && s.gridSize > 0) {
    const g = s.gridSize;
    if (!sx) dx = Math.round((start.x + dx) / g) * g - start.x;
    if (!sy) dy = Math.round((start.y + dy) / g) * g - start.y;
  }
  return { dx, dy, live: finish(moved(start, dx, dy), others, s) };
}

export function computeResize(start: Rect, rawDw: number, rawDh: number, others: Rect[], s: GuideSettings, ratio?: number) {
  let dw = rawDw, dh = rawDh, sx = false, sy = false;
  if (s.snapToElements) {
    const right = start.x + start.w + dw, bottom = start.y + start.h + dh;
    const bx = best([{ v: right, k: 'right' }], targetsX(others).map(t => t.r ? { ...t, k: 'right' } : t), s.snapDistance);
    if (bx) { dw += bx.d; sx = true; }
    const by = best([{ v: bottom, k: 'bottom' }], targetsY(others).map(t => t.r ? { ...t, k: 'bottom' } : t), s.snapDistance);
    if (by) { dh += by.d; sy = true; }
  }
  if (s.snapToGrid && s.gridSize > 0) {
    const g = s.gridSize;
    if (!sx) dw = Math.round((start.x + start.w + dw) / g) * g - start.x - start.w;
    if (!sy) dh = Math.round((start.y + start.h + dh) / g) * g - start.y - start.h;
  }
  if (ratio) dh = (start.w + dw) / ratio - start.h;
  const F = { ...start, w: Math.max(5, start.w + dw), h: Math.max(5, start.h + dh) };
  return { dw, dh, live: finish(F, others, s) };
}

/* ─── Alignment toolbar operations ─── */

export type AlignOp = 'left' | 'center' | 'right' | 'top' | 'middle' | 'bottom' | 'row' | 'column' | 'vspace' | 'hspace' | 'centerReceipt';

export function alignSelection(op: AlignOp, ids: string[], rects: RectMap, b: BrandingSettings): Record<string, Pos> {
  const items = ids.filter(id => rects[id]).map(id => ({ id, r: rects[id], p: getPos(b, id) }));
  if (!items.length) return {};
  const box = items.length > 1 ? unionAll(items.map(i => i.r))
    : { x: CONTENT.left, y: CONTENT.top, w: CONTENT.right - CONTENT.left, h: CONTENT.bottom - CONTENT.top, text: false };
  const anchor = items[0].r;
  const delta: Record<string, Pos> = {};
  const set = (id: string, dx: number, dy: number) => { delta[id] = { x: dx, y: dy }; };

  if (op === 'vspace' || op === 'hspace') {
    const v = op === 'vspace';
    const sorted = [...items].sort((a, c) => v ? a.r.y - c.r.y : a.r.x - c.r.x);
    if (sorted.length < 3) return {};
    const first = sorted[0].r, last = sorted[sorted.length - 1].r;
    const mid = sorted.slice(1, -1);
    const size = (r: Rect) => v ? r.h : r.w;
    const start = v ? first.y + first.h : first.x + first.w;
    const end = v ? last.y : last.x;
    const gap = (end - start - mid.reduce((s, i) => s + size(i.r), 0)) / (sorted.length - 1);
    let cursor = start + gap;
    for (const i of mid) {
      set(i.id, v ? 0 : cursor - i.r.x, v ? cursor - i.r.y : 0);
      cursor += size(i.r) + gap;
    }
  } else {
    const groupCx = unionAll(items.map(i => i.r));
    for (const { id, r } of items) {
      switch (op) {
        case 'left': set(id, box.x - r.x, 0); break;
        case 'center': set(id, box.x + box.w / 2 - (r.x + r.w / 2), 0); break;
        case 'right': set(id, box.x + box.w - (r.x + r.w), 0); break;
        case 'top': set(id, 0, box.y - r.y); break;
        case 'middle': set(id, 0, box.y + box.h / 2 - (r.y + r.h / 2)); break;
        case 'bottom': set(id, 0, box.y + box.h - (r.y + r.h)); break;
        case 'row': set(id, 0, anchor.y + anchor.h / 2 - (r.y + r.h / 2)); break;
        case 'column': set(id, anchor.x - r.x, 0); break;
        case 'centerReceipt': set(id, RECEIPT_W / 2 - (groupCx.x + groupCx.w / 2), 0); break;
      }
    }
  }
  const out: Record<string, Pos> = {};
  for (const i of items) if (delta[i.id]) out[i.id] = { x: i.p.x + delta[i.id].x, y: i.p.y + delta[i.id].y };
  return out;
}

export function getRotation(b: BrandingSettings, id: string) {
  if (id === 'logo') return b.logo.rotation;
  if (id === 'watermark') return -b.watermark.rotation;
  return b.watermark.customItems.find(c => c.id === id.slice(3))?.rotation ?? 0;
}

/** CSS-clockwise degrees. Watermark rotation is stored counter-clockwise (rotate(-deg)). */
export function setRotation(b: BrandingSettings, id: string, cssDeg: number): BrandingSettings {
  const d = Math.round(((cssDeg % 360) + 540) % 360 - 180);
  if (id === 'logo') return { ...b, logo: { ...b.logo, rotation: d } };
  if (id === 'watermark') return { ...b, watermark: { ...b.watermark, rotation: -d } };
  const wid = id.slice(3);
  return { ...b, watermark: { ...b.watermark, customItems: b.watermark.customItems.map(c => c.id === wid ? { ...c, rotation: d } : c) } };
}

import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';

export default createEndpoint({
  description: 'Fetches a logo/watermark image so exports can embed it',
  inputSchema: z.object({ url: z.string() }),
  outputSchema: z.object({ dataUrl: z.string() }),
  execute: async ({ input }) => {
    if (!/^https?:\/\//i.test(input.url)) throw new ZiteError('Invalid image URL');
    const res = await fetch(input.url);
    if (!res.ok) throw new ZiteError(`Image could not be loaded (${res.status})`);
    const type = res.headers.get('content-type')?.split(';')[0] || 'image/png';
    if (!type.startsWith('image/')) throw new ZiteError('URL is not an image');
    const buf = new Uint8Array(await res.arrayBuffer());
    let bin = '';
    for (let i = 0; i < buf.length; i += 0x8000) bin += String.fromCharCode(...buf.subarray(i, i + 0x8000));
    return { dataUrl: `data:${type};base64,${btoa(bin)}` };
  },
});

import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const START = 8146787n;
const MAX = 9999999999999999n;
const pad = (n: bigint) => n.toString().padStart(16, '0');

async function latest(): Promise<bigint | null> {
  const { rows } = await zite.sql({
    query: `SELECT "receiptNumber" FROM "IssuedReceipts" WHERE "receiptNumber" ~ '^[0-9]{16}$' ORDER BY "receiptNumber" DESC LIMIT 1`,
  });
  return rows[0] ? BigInt(String(rows[0].receiptNumber)) : null;
}

export default createEndpoint({
  description: 'Issues the next sequential 16-digit receipt number',
  inputSchema: z.object({ accountName: z.string(), total: z.number() }),
  outputSchema: z.object({ receiptNumber: z.string() }),
  execute: async ({ input }) => {
    for (let attempt = 0; attempt < 8; attempt++) {
      const prev = await latest();
      const next = prev === null ? START : prev + 1n;
      if (next > MAX) throw new ZiteError('Receipt number limit (9999999999999999) reached.');
      const receiptNumber = pad(next);
      const mine = await zite.issuedReceipts.create({
        record: { receiptNumber, accountName: input.accountName, total: input.total },
      });
      // If two requests claimed the same number at once, the earliest row keeps it; others retry.
      const { rows } = await zite.sql({
        query: `SELECT "id" FROM "IssuedReceipts" WHERE "receiptNumber" = $1 ORDER BY "sequence" ASC LIMIT 1`,
        params: [receiptNumber],
      });
      if (String(rows[0]?.id) === mine.id) return { receiptNumber };
      await zite.issuedReceipts.delete({ id: mine.id });
      await new Promise(r => setTimeout(r, 50 + Math.random() * 150));
    }
    throw new ZiteError('Could not issue a receipt number. Please try again.');
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { Email } from 'zitejs/email';
import { zite } from 'zitejs/db';

const SENDER = 'Connected Gmail account';

export default createEndpoint({
  description: 'Emails a receipt PDF (or a test message) and logs the result',
  inputSchema: z.object({
    to: z.string(),
    subject: z.string(),
    message: z.string(),
    attachmentUrl: z.string().optional(),
    attachmentFilename: z.string().optional(),
    receiptNumber: z.string().optional(),
    receiptId: z.string().optional(),
  }),
  outputSchema: z.object({ ok: z.boolean(), error: z.string().optional() }),
  execute: async ({ input }) => {
    const to = input.to.trim();
    let error: string | undefined;
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) error = 'Invalid recipient email address';
    else if (!input.subject.trim()) error = 'Subject is required';
    if (!error) {
      try {
        await Email.send({
          to,
          subject: input.subject,
          layout: 'plain',
          body: [{ type: 'text', content: input.message }],
          attachments: input.attachmentUrl && input.attachmentFilename
            ? [{ filename: input.attachmentFilename, url: input.attachmentUrl, contentType: 'application/pdf' }]
            : undefined,
        });
      } catch (e) {
        error = e instanceof Error ? e.message : 'Send failed';
      }
    }
    if (input.receiptNumber) {
      await zite.emailLog.create({
        record: {
          receiptNumber: input.receiptNumber, receiptId: input.receiptId ?? null,
          recipientEmail: /@/.test(to) ? to : null, subject: input.subject, message: input.message,
          attachmentFilename: input.attachmentFilename ?? null, sendingAccount: SENDER,
          status: error ? 'FAILED' : 'SENT', errorMessage: error ?? null,
          sentAt: error ? null : new Date().toISOString(),
        },
      });
    }
    return error ? { ok: false, error } : { ok: true };
  },
});

