import { useLayoutEffect, useRef, useState, type RefObject } from 'react';
import { type ReceiptData, type BrandingSettings, type TextElementId, RECEIPT_W } from '../types';
import {
  type GuideSettings, type LiveGuides, type RectMap, type Pos, type Rect,
  measureElements, hitTest, getPos, setPositions, getSize, setSize, computeMove, computeResize, computeMeasures,
  isGraphic, getRotation, setRotation,
} from '../alignment';
import ReceiptPreview from './ReceiptPreview';
import GuideOverlay from './GuideOverlay';

interface Props {
  data: ReceiptData;
  branding: BrandingSettings;
  onBrandingChange: (b: BrandingSettings) => void;
  receiptRef: RefObject<HTMLDivElement>;
  selection: string[];
  onSelectionChange: (ids: string[]) => void;
  settings: GuideSettings;
  onTextClick: (id: TextElementId) => void;
  onGraphicClick: (id: string) => void;
  scale?: number;
}

type Drag = {
  mode: 'move' | 'resize' | 'rotate'; id: string; ids: string[]; sx: number; sy: number; k: number; origin: DOMRect;
  rects: RectMap; starts: Record<string, Pos>; size: { w: number; h: number }; rot: number; angle0: number;
  base: BrandingSettings; moved: boolean;
};

const NO_SNAP = { snapToElements: false, smartGuides: false, showMeasurements: false };

export default function EditorCanvas({ data, branding, onBrandingChange, receiptRef, selection, onSelectionChange, settings, onTextClick, onGraphicClick, scale = 1 }: Props) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const drag = useRef<Drag | null>(null);
  const [rects, setRects] = useState<RectMap>({});
  const [live, setLive] = useState<LiveGuides | null>(null);

  useLayoutEffect(() => {
    if (receiptRef.current) setRects(measureElements(receiptRef.current));
  }, [branding, data, selection, receiptRef]);

  const toLocal = (d: { origin: DOMRect; k: number }, e: { clientX: number; clientY: number }) =>
    ({ x: (e.clientX - d.origin.left) / d.k, y: (e.clientY - d.origin.top) / d.k });

  const begin = (e: React.PointerEvent, mode: Drag['mode'], id: string, ids: string[]) => {
    const canvas = receiptRef.current!;
    const origin = canvas.getBoundingClientRect();
    const k = origin.width / RECEIPT_W;
    const rs = measureElements(canvas);
    const r = rs[id];
    const p = { x: (e.clientX - origin.left) / k, y: (e.clientY - origin.top) / k };
    drag.current = {
      mode, id, ids, sx: e.clientX, sy: e.clientY, k, origin, rects: rs,
      starts: Object.fromEntries(ids.map(i => [i, getPos(branding, i)])),
      size: getSize(branding, id), rot: getRotation(branding, id),
      angle0: r ? Math.atan2(p.y - (r.y + r.h / 2), p.x - (r.x + r.w / 2)) : 0,
      base: branding, moved: false,
    };
    wrapRef.current?.setPointerCapture(e.pointerId);
  };

  const onPointerDown = (e: React.PointerEvent) => {
    const canvas = receiptRef.current;
    if (!canvas || e.button !== 0) return;
    const cr = canvas.getBoundingClientRect();
    const k = cr.width / RECEIPT_W;
    const hit = hitTest(measureElements(canvas), (e.clientX - cr.left) / k, (e.clientY - cr.top) / k);
    const multi = e.shiftKey || e.metaKey || e.ctrlKey;
    if (!hit) { if (!multi) onSelectionChange([]); return; }
    if (multi && hit !== 'watermark') {
      onSelectionChange(selection.includes(hit) ? selection.filter(i => i !== hit) : [...selection.filter(i => i !== 'watermark'), hit]);
      return;
    }
    const ids = selection.includes(hit) ? selection : [hit];
    if (ids !== selection) onSelectionChange(ids);
    begin(e, 'move', hit, ids);
  };

  const onPointerMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    if (!d.moved && Math.hypot(e.clientX - d.sx, e.clientY - d.sy) < 3) return;
    d.moved = true;
    const dx = (e.clientX - d.sx) / d.k, dy = (e.clientY - d.sy) / d.k;
    const others: Rect[] = Object.entries(d.rects).filter(([i]) => !d.ids.includes(i) && i !== 'watermark').map(([, r]) => r);
    const start = d.rects[d.id];
    if (!start) return;
    const isPattern = d.id === 'watermark';

    if (d.mode === 'rotate') {
      const p = toLocal(d, e);
      let deg = d.rot + ((Math.atan2(p.y - (start.y + start.h / 2), p.x - (start.x + start.w / 2)) - d.angle0) * 180) / Math.PI;
      if (e.shiftKey) deg = Math.round(deg / 15) * 15;
      onBrandingChange(setRotation(d.base, d.id, deg));
      setLive({ rect: start, guides: [], labels: [`ROTATION ${Math.round(((deg % 360) + 540) % 360 - 180)}°`] });
    } else if (d.mode === 'move') {
      const res = computeMove(start, dx, dy, isPattern ? [] : others, isPattern ? { ...settings, ...NO_SNAP } : settings);
      const pos = Object.fromEntries(d.ids.map(i => [i, { x: d.starts[i].x + res.dx, y: d.starts[i].y + res.dy }]));
      onBrandingChange(setPositions(d.base, pos));
      setLive(isPattern ? { rect: start, guides: [], labels: [] } : res.live);
    } else {
      const lock = isPattern || (d.id === 'logo' && d.base.logo.lockAspect);
      const ratio = lock && d.size.h ? d.size.w / d.size.h : undefined;
      if (isPattern) {
        const w = Math.max(10, d.size.w + dx);
        onBrandingChange(setSize(d.base, d.id, w, w / (ratio || 1)));
        setLive({ rect: start, guides: [], labels: [`LOGO SIZE ${Math.round(w)} PX`] });
      } else {
        const res = computeResize(start, dx, dy, others, settings, ratio);
        onBrandingChange(setSize(d.base, d.id, d.size.w + res.dw, d.size.h + res.dh));
        setLive(res.live);
      }
    }
  };

  const onPointerUp = () => {
    const d = drag.current;
    drag.current = null;
    setLive(null);
    if (!d || d.moved || d.mode !== 'move') return;
    if (isGraphic(d.id)) onGraphicClick(d.id);
    else onTextClick(d.id as TextElementId);
  };

  const sole = selection.length === 1 ? selection[0] : null;
  const idleMeasures = !live && settings.showMeasurements && sole && sole !== 'watermark' && rects[sole]
    ? computeMeasures(rects[sole], Object.entries(rects).filter(([i]) => i !== sole && i !== 'watermark').map(([, r]) => r))
    : undefined;

  return (
    <div ref={wrapRef} className="relative select-none"
      // With nothing selected, touch swipes scroll the page; once something is selected, touch drags it.
      style={{ cursor: live ? 'grabbing' : 'default', touchAction: selection.length ? 'none' : 'pan-x pan-y pinch-zoom' }}
      onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerCancel={onPointerUp}>
      <ReceiptPreview data={data} branding={branding} receiptRef={receiptRef} />
      <GuideOverlay settings={settings} rects={rects} selection={selection} live={live} idleMeasures={idleMeasures} scale={scale}
        onHandleStart={(e, id, mode) => { e.stopPropagation(); begin(e, mode, id, [id]); }} />
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useUpload } from 'zitejs/upload';
import { sendReceiptEmail } from 'zitejs/api';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@project/components/ui/dialog';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Textarea } from '@project/components/ui/textarea';
import { Label } from '@project/components/ui/label';
import { CheckCircle2, FileText, Loader2, RotateCcw, XCircle } from 'lucide-react';
import { type SavedReceipt } from '../types';
import { isEmail } from '../utils';

export const defaultSubject = (r: SavedReceipt) => `Your Receipt – ${r.receiptNumber}`;
export const defaultMessage = (r: SavedReceipt) => {
  const name = r.accountName?.trim();
  return `${name ? `Good day, ${name}!` : 'Good day!'}

Thank you for your payment.

Please find attached your receipt for your reference and records.

Receipt Number: ${r.receiptNumber}
Transaction Date: ${r.date}
Amount Paid: PHP ${r.amount}

Should you have any questions or concerns regarding this receipt, please feel free to contact us.

Thank you for choosing Converge.

Regards,
Converge`;
};

type Step = 'compose' | 'confirm' | 'sending' | 'sent' | 'failed';

interface Props {
  receipt: SavedReceipt | null;
  onClose: () => void;
  renderPdf: () => Promise<Blob>;
  onStatus: (id: string, status: 'Sent' | 'Failed') => void;
}

export default function EmailDialog({ receipt, onClose, renderPdf, onStatus }: Props) {
  const { upload } = useUpload();
  const [to, setTo] = useState('');
  const [subject, setSubject] = useState('');
  const [message, setMessage] = useState('');
  const [step, setStep] = useState<Step>('compose');
  const [touched, setTouched] = useState(false);

  useEffect(() => {
    if (!receipt) return;
    setTo(receipt.data.customerEmail ?? ''); setSubject(defaultSubject(receipt)); setMessage(defaultMessage(receipt));
    setStep('compose'); setTouched(false);
  }, [receipt]);

  if (!receipt) return null;
  const filename = `Receipt_${receipt.receiptNumber}.pdf`;
  const toErr = !to.trim() ? 'Recipient is required' : !isEmail(to) ? 'Enter a valid email address' : '';
  const valid = !toErr && subject.trim().length > 0;

  const send = async () => {
    setStep('sending');
    try {
      const blob = await renderPdf();
      const { url } = await upload(new File([blob], filename, { type: 'application/pdf' }));
      const res = await sendReceiptEmail({ to: to.trim(), subject, message, attachmentUrl: url, attachmentFilename: filename, receiptNumber: receipt.receiptNumber, receiptId: receipt.id });
      if (!res.ok) throw new Error(res.error);
      onStatus(receipt.id, 'Sent'); setStep('sent');
    } catch (e) {
      console.error(e); onStatus(receipt.id, 'Failed'); setStep('failed');
    }
  };

  const attachment = (
    <div className="flex min-w-0 items-center gap-2 rounded-md border bg-muted/60 px-3 py-2.5 text-sm">
      <FileText className="h-4 w-4 shrink-0 text-primary" /><span className="truncate font-medium">{filename}</span>
    </div>
  );

  return (
    <Dialog open onOpenChange={o => { if (!o && step !== 'sending') onClose(); }}>
      <DialogContent className="touch-ui flex max-h-[92dvh] w-[calc(100vw-1.5rem)] max-w-lg flex-col gap-4 overflow-y-auto p-4 sm:p-6">
        <DialogHeader className="text-left">
          <DialogTitle>{step === 'compose' ? 'Email receipt' : 'Send receipt?'}</DialogTitle>
          <DialogDescription>Receipt #{receipt.receiptNumber}</DialogDescription>
        </DialogHeader>

        {step === 'compose' && (
          <div className="space-y-3">
            <div className="space-y-1.5">
              <Label htmlFor="em-to">To</Label>
              <Input id="em-to" type="email" inputMode="email" className="h-11" value={to} onChange={e => setTo(e.target.value)} onBlur={() => setTouched(true)} aria-invalid={touched && !!toErr} placeholder="customer@example.com" />
              {touched && toErr && <p className="text-xs text-destructive">{toErr}</p>}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="em-subj">Subject</Label>
              <Input id="em-subj" className="h-11" value={subject} onChange={e => setSubject(e.target.value)} />
            </div>
            <div className="space-y-1.5">
              <div className="flex items-center justify-between gap-2">
                <Label htmlFor="em-msg">Message</Label>
                <Button type="button" variant="ghost" size="sm" className="h-11 gap-1.5" onClick={() => { setMessage(defaultMessage(receipt)); setSubject(defaultSubject(receipt)); }}>
                  <RotateCcw className="h-4 w-4" />Reset to default
                </Button>
              </div>
              <Textarea id="em-msg" rows={11} className="text-base sm:text-sm" value={message} onChange={e => setMessage(e.target.value)} />
            </div>
            <div className="space-y-1.5"><Label>Attachment</Label>{attachment}</div>
          </div>
        )}

        {(step === 'confirm' || step === 'sending') && (
          <dl className="space-y-2 text-sm">
            <div><dt className="text-muted-foreground">To</dt><dd className="break-all font-medium">{to}</dd></div>
            <div><dt className="text-muted-foreground">Subject</dt><dd className="break-words font-medium">{subject}</dd></div>
            <div><dt className="mb-1 text-muted-foreground">Attachment</dt><dd>{attachment}</dd></div>
          </dl>
        )}

        {step === 'sent' && <p className="flex items-center gap-2 font-medium text-primary"><CheckCircle2 className="h-5 w-5" />Receipt sent successfully.</p>}
        {step === 'failed' && <p className="flex items-start gap-2 text-sm text-destructive"><XCircle className="mt-0.5 h-5 w-5 shrink-0" />Unable to send the receipt. Please check the email connection and recipient address, then try again.</p>}

        <DialogFooter className="flex-col-reverse gap-2 sm:flex-row">
          {step === 'compose' && <>
            <Button variant="outline" className="h-11" onClick={onClose}>Cancel</Button>
            <Button className="h-11" disabled={!valid} onClick={() => setStep('confirm')}>Send email</Button>
          </>}
          {(step === 'confirm' || step === 'sending') && <>
            <Button variant="outline" className="h-11" disabled={step === 'sending'} onClick={() => setStep('compose')}>Cancel</Button>
            <Button className="h-11 gap-2" disabled={step === 'sending'} onClick={send}>
              {step === 'sending' ? <><Loader2 className="h-4 w-4 animate-spin" />Sending receipt...</> : 'Send email'}
            </Button>
          </>}
          {step === 'sent' && <Button className="h-11" onClick={onClose}>Done</Button>}
          {step === 'failed' && <>
            <Button variant="outline" className="h-11" onClick={() => setStep('compose')}>Edit</Button>
            <Button className="h-11" onClick={send}>Try again</Button>
          </>}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { sendReceiptEmail } from 'zitejs/api';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Loader2, MailCheck, Send } from 'lucide-react';
import { toast } from 'sonner';
import { PanelHeader, Section, Field } from './kit';
import { isEmail } from '../utils';

export default function EmailSettings() {
  const [to, setTo] = useState('');
  const [busy, setBusy] = useState(false);
  const err = to && !isEmail(to) ? 'Enter a valid email address' : '';

  const test = async () => {
    setBusy(true);
    try {
      const res = await sendReceiptEmail({
        to: to.trim(), subject: 'Test email – Converge Receipt Maker',
        message: 'This is a test email from Converge Receipt Maker.\n\nIf you received it, the connected email account is working.',
      });
      if (!res.ok) throw new Error(res.error);
      toast.success(`Test email sent to ${to.trim()}`);
    } catch {
      toast.error('Test email failed. Please check the email connection and address.');
    } finally { setBusy(false); }
  };

  return (
    <div className="space-y-4">
      <PanelHeader title="Email" description="Receipts are sent from the connected email account." />
      <Section title="Email account">
        <div className="flex items-start gap-3">
          <MailCheck className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
          <div className="min-w-0 text-sm">
            <p><span className="text-muted-foreground">Status:</span> <span className="font-semibold">Connected</span></p>
            <p><span className="text-muted-foreground">Account:</span> Gmail / Google Workspace (connected securely — no password is stored)</p>
            <p className="mt-2 text-xs text-muted-foreground">To connect or change the sending account, the app owner can reconnect it from the Zite editor's Integrations panel.</p>
          </div>
        </div>
      </Section>
      <Section title="Send test email">
        <Field label="Test address" error={err}>
          <Input type="email" inputMode="email" className="h-11" value={to} onChange={e => setTo(e.target.value)} placeholder="you@example.com" />
        </Field>
        <Button className="h-11 w-full gap-2 sm:w-auto" disabled={busy || !isEmail(to)} onClick={test}>
          {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}Send test email
        </Button>
      </Section>
    </div>
  );
}

import { type GuideSettings, type LiveGuides, type RectMap, type Measures, CONTENT, elementLabel, isResizable, isRotatable } from '../alignment';
import { RotateCw } from 'lucide-react';

const GUIDE = '#ec4899';
const MEASURE = '#0ea5e9';

interface Props {
  settings: GuideSettings;
  rects: RectMap;
  selection: string[];
  live: LiveGuides | null;
  idleMeasures?: Measures;
  onHandleStart: (e: React.PointerEvent, id: string, mode: 'resize' | 'rotate') => void;
  scale?: number;
}

const COARSE = typeof window !== 'undefined' && window.matchMedia?.('(pointer: coarse)').matches;

/** Editor-only overlay. Rendered OUTSIDE the receipt node so it never reaches print/PDF/PNG. */
export default function GuideOverlay({ settings, rects, selection, live, idleMeasures, onHandleStart, scale = 1 }: Props) {
  // Handles keep a constant ON-SCREEN size regardless of preview zoom (bigger on touch screens).
  const hs = (COARSE ? 32 : 16) / scale;
  const g = Math.max(2, settings.gridSize);
  const measures = live?.measures ?? idleMeasures;
  const mRect = live?.rect ?? (selection.length === 1 ? rects[selection[0]] : undefined);
  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden" style={{ zIndex: 20 }}>
      {settings.showGrid && (
        <div className="absolute inset-0" style={{
          backgroundImage: `linear-gradient(to right, hsl(var(--primary) / 0.28) 1px, transparent 1px), linear-gradient(to bottom, hsl(var(--primary) / 0.28) 1px, transparent 1px), linear-gradient(to right, hsl(var(--primary) / 0.12) 1px, transparent 1px), linear-gradient(to bottom, hsl(var(--primary) / 0.12) 1px, transparent 1px)`,
          backgroundSize: `${g * 5}px ${g * 5}px, ${g * 5}px ${g * 5}px, ${g}px ${g}px, ${g}px ${g}px`,
        }} />
      )}

      {selection.map(id => {
        const r = rects[id];
        if (!r) return null;
        const pattern = id === 'watermark';
        const pad = pattern ? -3 : 2;
        const single = selection.length === 1;
        return (
          <div key={id} className="absolute" style={{
            left: r.x - pad, top: r.y - pad, width: r.w + pad * 2, height: r.h + pad * 2,
            border: `1.5px ${pattern ? 'dashed' : 'solid'} hsl(var(--primary))`, borderRadius: 3,
            background: pattern ? 'transparent' : 'hsl(var(--primary) / 0.05)',
          }}>
            {single && !live && (
              <span className={`absolute left-0 whitespace-nowrap rounded bg-primary px-1.5 py-0.5 text-[10px] font-semibold text-primary-foreground ${pattern ? 'top-2 left-2' : '-top-5'}`}>
                {elementLabel(id)}{pattern ? ' — drag to shift · corner to resize · ↻ to rotate' : ''}
              </span>
            )}
            {single && isRotatable(id) && (
              <>
                {!pattern && <div className="absolute left-1/2 border-l border-primary" style={{ top: -hs, height: hs }} />}
                <button type="button" title="Rotate (hold Shift to snap 15°)" aria-label="Rotate"
                  onPointerDown={e => onHandleStart(e, id, 'rotate')}
                  style={{ width: hs, height: hs, top: pattern ? 8 / scale : -hs * 2, touchAction: 'none' }}
                  className="absolute left-1/2 -translate-x-1/2 flex items-center justify-center rounded-full border-2 border-primary bg-background text-primary cursor-grab pointer-events-auto">
                  <RotateCw style={{ width: hs * 0.6, height: hs * 0.6 }} />
                </button>
              </>
            )}
            {single && isResizable(id) && (
              <div title="Resize" onPointerDown={e => onHandleStart(e, id, 'resize')}
                style={pattern
                  ? { width: hs * 0.8, height: hs * 0.8, bottom: 8 / scale, right: 8 / scale, touchAction: 'none' }
                  : { width: hs * 0.8, height: hs * 0.8, bottom: -hs * 0.4, right: -hs * 0.4, touchAction: 'none' }}
                className="absolute cursor-nwse-resize rounded-sm border-2 border-primary bg-background pointer-events-auto" />
            )}
          </div>
        );
      })}

      {live?.guides.map((gd, i) => gd.axis === 'x'
        ? <div key={i} className="absolute" style={{ left: gd.pos, top: gd.from - 6, height: gd.to - gd.from + 12, borderLeft: `1px dashed ${GUIDE}` }} />
        : <div key={i} className="absolute" style={{ top: gd.pos, left: gd.from - 6, width: gd.to - gd.from + 12, borderTop: `1px dashed ${GUIDE}` }} />)}

      {measures && mRect && <MeasureLines m={measures} r={mRect} />}

      {live && live.labels.length > 0 && (
        <div className="absolute flex flex-wrap gap-1" style={{ left: live.rect.x, top: Math.max(2, live.rect.y - 22) }}>
          {live.labels.map(l => (
            <span key={l} className="whitespace-nowrap rounded px-1.5 py-0.5 text-[9px] font-bold tracking-wide text-white shadow"
              style={{ background: l === 'EQUAL SPACING' ? MEASURE : GUIDE }}>ALIGNED — {l}</span>
          ))}
        </div>
      )}
    </div>
  );
}

function MeasureLines({ m, r }: { m: Measures; r: { x: number; y: number; w: number; h: number } }) {
  const cy = r.y + r.h / 2;
  const tag = (v: number) => `${Math.round(v)}px`;
  return (
    <>
      {m.above && <VLine x={m.above.x} from={m.above.from} to={m.above.to} label={tag(m.above.to - m.above.from)} equal={m.equal} />}
      {m.below && <VLine x={m.below.x} from={m.below.from} to={m.below.to} label={tag(m.below.to - m.below.from)} equal={m.equal} />}
      <HLine y={cy} from={CONTENT.left} to={r.x} label={tag(m.left)} />
      <HLine y={cy} from={r.x + r.w} to={CONTENT.right} label={tag(m.right)} />
    </>
  );
}

function VLine({ x, from, to, label, equal }: { x: number; from: number; to: number; label: string; equal: boolean }) {
  if (to - from < 1) return null;
  return (
    <div className="absolute" style={{ left: x, top: from, height: to - from, borderLeft: `1px solid ${MEASURE}` }}>
      <span className="absolute left-1 top-1/2 -translate-y-1/2 whitespace-nowrap rounded px-1 text-[9px] font-semibold text-white" style={{ background: MEASURE }}>
        {label}{equal ? ' =' : ''}
      </span>
    </div>
  );
}

function HLine({ y, from, to, label }: { y: number; from: number; to: number; label: string }) {
  if (to - from < 1) return null;
  return (
    <div className="absolute" style={{ top: y, left: from, width: to - from, borderTop: `1px dotted ${MEASURE}` }}>
      <span className="absolute -top-3.5 left-1/2 -translate-x-1/2 whitespace-nowrap rounded px-1 text-[9px] font-semibold text-white" style={{ background: MEASURE }}>{label}</span>
    </div>
  );
}

import { type GuideSettings, type AlignOp, type Pos, elementLabel } from '../alignment';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { cn } from '@project/components/lib/utils';
import {
  Grid3x3, Magnet, Ruler, Crosshair, ScanLine, Link2, AlignStartVertical, AlignCenterVertical, AlignEndVertical,
  AlignStartHorizontal, AlignCenterHorizontal, AlignEndHorizontal, Rows3, Columns3,
  AlignVerticalDistributeCenter, AlignHorizontalDistributeCenter, X,
} from 'lucide-react';

const PRESETS = [5, 10, 20, 25, 50];

interface Props {
  settings: GuideSettings;
  onSettings: (g: GuideSettings) => void;
  selection: string[];
  onClearSelection: () => void;
  onAlign: (op: AlignOp) => void;
  position: Pos | null;
  onPosition: (p: Pos) => void;
}

export default function GuideToolbar({ settings: s, onSettings, selection, onClearSelection, onAlign, position, onPosition }: Props) {
  const set = (patch: Partial<GuideSettings>) => onSettings({ ...s, ...patch });
  const n = selection.length;
  const custom = !PRESETS.includes(s.gridSize);
  return (
    <div className="z-30 border-b bg-card/95 backdrop-blur px-3 py-2.5 space-y-2 lg:sticky lg:top-0 lg:px-4">
      <div className="hidden flex-wrap items-center gap-1.5 md:flex">
        <Toggle on={s.showGrid} onClick={() => set({ showGrid: !s.showGrid })} icon={<Grid3x3 />} label="Show Grid" />
        <Toggle on={s.snapToGrid} onClick={() => set({ snapToGrid: !s.snapToGrid })} icon={<Magnet />} label="Snap to Grid" />
        <Toggle on={s.smartGuides} onClick={() => set({ smartGuides: !s.smartGuides })} icon={<ScanLine />} label="Smart Guides" />
        <Toggle on={s.snapToElements} onClick={() => set({ snapToElements: !s.snapToElements })} icon={<Link2 />} label="Snap to Elements" />
        <Toggle on={s.showMeasurements} onClick={() => set({ showMeasurements: !s.showMeasurements })} icon={<Ruler />} label="Show Measurements" />
        <div className="flex items-center gap-1 ml-1">
          <span className="text-xs text-muted-foreground">Grid</span>
          <Select value={custom ? 'custom' : String(s.gridSize)} onValueChange={v => set({ gridSize: v === 'custom' ? (custom ? s.gridSize : 15) : Number(v) })}>
            <SelectTrigger className="h-7 w-[84px] text-xs"><SelectValue /></SelectTrigger>
            <SelectContent>
              {PRESETS.map(p => <SelectItem key={p} value={String(p)}>{p} px</SelectItem>)}
              <SelectItem value="custom">Custom</SelectItem>
            </SelectContent>
          </Select>
          {custom && <Input type="number" min={2} max={200} className="h-7 w-14 text-xs" value={s.gridSize}
            onChange={e => set({ gridSize: Math.max(2, Math.min(200, Number(e.target.value) || 2)) })} />}
          <span className="text-xs text-muted-foreground ml-1">Snap dist.</span>
          <Input type="number" min={1} max={30} className="h-7 w-12 text-xs" value={s.snapDistance}
            onChange={e => set({ snapDistance: Math.max(1, Math.min(30, Number(e.target.value) || 1)) })} />
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-1">
        <span className="text-xs font-medium text-muted-foreground mr-1 min-w-[88px]">
          {n === 0 ? 'Tap / click an element (Shift = multi)' : n === 1 ? elementLabel(selection[0]) : `${n} selected`}
        </span>
        <AB op="left" t="Align Left" i={<AlignStartVertical />} d={n < 1} f={onAlign} />
        <AB op="center" t="Align Center" i={<AlignCenterVertical />} d={n < 1} f={onAlign} />
        <AB op="right" t="Align Right" i={<AlignEndVertical />} d={n < 1} f={onAlign} />
        <AB op="top" t="Align Top" i={<AlignStartHorizontal />} d={n < 1} f={onAlign} />
        <AB op="middle" t="Align Middle" i={<AlignCenterHorizontal />} d={n < 1} f={onAlign} />
        <AB op="bottom" t="Align Bottom" i={<AlignEndHorizontal />} d={n < 1} f={onAlign} />
        <AB op="row" t="Same Row (match first selected)" i={<Rows3 />} d={n < 2} f={onAlign} />
        <AB op="column" t="Same Column (match first selected)" i={<Columns3 />} d={n < 2} f={onAlign} />
        <AB op="vspace" t="Equal Vertical Spacing (3+)" i={<AlignVerticalDistributeCenter />} d={n < 3} f={onAlign} />
        <AB op="hspace" t="Equal Horizontal Spacing (3+)" i={<AlignHorizontalDistributeCenter />} d={n < 3} f={onAlign} />
        <AB op="centerReceipt" t="Center on Receipt" i={<Crosshair />} d={n < 1} f={onAlign} />
        {position && (
          <div className="flex items-center gap-1 ml-2">
            <span className="text-xs text-muted-foreground">X</span>
            <Input type="number" className="h-7 w-16 text-xs" value={position.x} onChange={e => onPosition({ ...position, x: Number(e.target.value) || 0 })} />
            <span className="text-xs text-muted-foreground">Y</span>
            <Input type="number" className="h-7 w-16 text-xs" value={position.y} onChange={e => onPosition({ ...position, y: Number(e.target.value) || 0 })} />
          </div>
        )}
        {n > 0 && <Button size="sm" variant="outline" className="ml-auto h-8 gap-1" title="Clear selection" onClick={onClearSelection}><X className="h-3.5 w-3.5" />Done</Button>}
      </div>
    </div>
  );
}

function Toggle({ on, onClick, icon, label }: { on: boolean; onClick: () => void; icon: React.ReactNode; label: string }) {
  return (
    <button onClick={onClick} aria-pressed={on}
      className={cn('flex h-7 items-center gap-1 rounded-md border px-2 text-xs font-medium transition-colors [&_svg]:h-3.5 [&_svg]:w-3.5',
        on ? 'border-primary bg-primary text-primary-foreground' : 'bg-background text-muted-foreground hover:text-foreground')}>
      {icon}{label}
    </button>
  );
}

function AB({ op, t, i, d, f }: { op: AlignOp; t: string; i: React.ReactNode; d: boolean; f: (op: AlignOp) => void }) {
  return (
    <Button size="icon" variant="outline" className="h-7 w-7 [&_svg]:h-3.5 [&_svg]:w-3.5" title={t} aria-label={t} disabled={d} onClick={() => f(op)}>
      {i}
    </Button>
  );
}

import { useEffect, useRef, useState } from 'react';
import { type LineItem, newLineItem, lineAmount, money } from '../types';
import { Input } from '@project/components/ui/input';
import { Button } from '@project/components/ui/button';
import { Label } from '@project/components/ui/label';
import { Plus, X, AlertCircle } from 'lucide-react';
import { toast } from 'sonner';
import { Section } from './kit';

interface Props {
  items: LineItem[];
  onChange: (items: LineItem[]) => void;
  errors: Record<string, string>;
  disabled?: boolean;
}

// Table layout from `sm` up; below that each line is a stacked card.
const COLS = 'sm:grid sm:grid-cols-[minmax(0,1fr)_56px_92px_84px_36px] sm:gap-2 sm:items-center';
const num = (v: string) => v.replace(/[^0-9.,]/g, '');
const errText = (e: string) => e === '> 0' ? 'Quantity must be more than 0' : e === 'Invalid' ? 'Enter a valid unit price' : 'Description is required';

export default function LineItemsEditor({ items, onChange, errors, disabled }: Props) {
  const update = (id: string, patch: Partial<LineItem>) => onChange(items.map(i => i.id === id ? { ...i, ...patch } : i));
  const rowRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const [added, setAdded] = useState<string | null>(null);
  const [announce, setAnnounce] = useState('');
  const addRef = useRef<HTMLButtonElement>(null);
  const focusAfterRemove = useRef<number | null>(null);

  useEffect(() => {
    if (!added) return;
    const row = rowRefs.current[added];
    row?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    row?.querySelector('input')?.focus({ preventScroll: true });
    setAdded(null);
  }, [added]);

  const add = () => {
    const it = newLineItem(); onChange([...items, it]); setAdded(it.id);
    setAnnounce(`Transaction ${items.length + 1} added. Enter its description.`);
  };

  const remove = (n: number) => {
    const before = items;
    const gone = items[n];
    onChange(items.filter((_, i) => i !== n));
    focusAfterRemove.current = Math.min(n, items.length - 2);
    const label = gone.description.trim() || `Transaction ${n + 1}`;
    setAnnounce(`Transaction ${n + 1} removed.`);
    toast(`Removed ${label}`, { action: { label: 'Undo', onClick: () => { onChange(before); setAnnounce(`Transaction ${n + 1} restored.`); } } });
  };

  // Never leave focus on a deleted row: move it to the same position's row (or the previous one).
  useEffect(() => {
    const idx = focusAfterRemove.current;
    if (idx === null) return;
    focusAfterRemove.current = null;
    const target = items[idx] ? rowRefs.current[items[idx].id]?.querySelector('input') : null;
    (target ?? addRef.current)?.focus();
  }, [items]);

  return (
    <Section title={`Transactions / Services · ${items.length}`}>
      <div aria-hidden className={`hidden ${COLS} text-xs font-medium text-muted-foreground`}>
        <span>Description</span><span>Qty</span><span>Unit price</span><span className="text-right">Amount</span><span />
      </div>
      <div className="space-y-3 sm:space-y-2">
        {items.map((it, n) => {
          const e = (k: string) => errors[`item-${n}-${k}`];
          const err = e('description') || e('quantity') || e('unitPrice');
          return (
            <div key={it.id} ref={el => { rowRefs.current[it.id] = el; }} role="group" aria-label={`Transaction ${n + 1}`}
              className="rounded-lg border bg-background p-3 sm:rounded-none sm:border-0 sm:bg-transparent sm:p-0">
              <div className="mb-2 flex items-center justify-between sm:hidden">
                <h4 className="text-sm font-semibold">Transaction {n + 1}</h4>
                <RemoveBtn n={n + 1} disabled={disabled || items.length <= 1} onClick={() => remove(n)} />
              </div>
              <div className={`space-y-2 sm:space-y-0 ${COLS}`}>
                <Cell label="Description">
                  <Input disabled={disabled} value={it.description} placeholder="e.g. RELOCATION FEE" aria-label={`Transaction ${n + 1} description`} aria-describedby={e('description') ? `${it.id}-err` : undefined} enterKeyHint="next"
                    onChange={ev => update(it.id, { description: ev.target.value })} aria-invalid={!!e('description')}
                    className={e('description') ? 'border-destructive' : ''} />
                </Cell>
                <div className="grid grid-cols-2 gap-2 sm:contents">
                  <Cell label="Quantity">
                    <Input disabled={disabled} inputMode="decimal" value={it.quantity} aria-label={`Transaction ${n + 1} quantity`} aria-invalid={!!e('quantity')} aria-describedby={e('quantity') ? `${it.id}-err` : undefined} className={`text-right sm:px-2 ${e('quantity') ? 'border-destructive' : ''}`}
                      onChange={ev => update(it.id, { quantity: num(ev.target.value) })} />
                  </Cell>
                  <Cell label="Unit price">
                    <Input disabled={disabled} inputMode="decimal" value={it.unitPrice} placeholder="0.00" aria-label={`Transaction ${n + 1} unit price`} aria-invalid={!!e('unitPrice')} aria-describedby={e('unitPrice') ? `${it.id}-err` : undefined} className={`text-right sm:px-2 ${e('unitPrice') ? 'border-destructive' : ''}`}
                      onChange={ev => update(it.id, { unitPrice: num(ev.target.value) })} />
                  </Cell>
                </div>
                <div className="flex items-center justify-between border-t pt-2 sm:block sm:border-0 sm:pt-0 sm:text-right">
                  <span className="text-sm text-muted-foreground sm:hidden">Amount</span>
                  <span aria-label={`Transaction ${n + 1} amount PHP ${money(lineAmount(it))}`} className="text-base font-semibold tabular-nums sm:text-sm"><span className="sm:hidden">PHP </span>{money(lineAmount(it))}</span>
                </div>
                <div className="hidden sm:block">
                  <RemoveBtn n={n + 1} disabled={disabled || items.length <= 1} onClick={() => remove(n)} />
                </div>
              </div>
              {err && <p id={`${it.id}-err`} className="mt-1 flex items-center gap-1 text-xs font-medium text-destructive"><AlertCircle className="h-3.5 w-3.5 shrink-0" aria-hidden />Transaction {n + 1}: {errText(err)}</p>}
            </div>
          );
        })}
      </div>
      {!disabled && (
        <Button ref={addRef} variant="outline" aria-label={`Add transaction (currently ${items.length})`} className="h-11 w-full gap-2 border-dashed border-primary/50 text-primary hover:text-primary" onClick={add}>
