import { useEffect, useLayoutEffect, useRef, useState, type ReactNode, type RefObject } from 'react';
import { RECEIPT_W } from '../types';
import { Button } from '@project/components/ui/button';
import { Minus, Plus, Maximize2 } from 'lucide-react';

interface Props {
  receiptRef: RefObject<HTMLDivElement>;
  children: (scale: number) => ReactNode;
}

const MIN = 0.25, MAX = 2, STEP = 0.1;

/**
 * Display-only zoom. The receipt keeps its fixed width and natural height; we only apply a
 * uniform CSS scale to a wrapper and reserve the scaled box so nothing is cropped.
 * Exports read the receipt node itself and divide out this scale, so output never depends on it.
 */
export default function PreviewPane({ receiptRef, children }: Props) {
  const boxRef = useRef<HTMLDivElement>(null);
  const [avail, setAvail] = useState(RECEIPT_W);
  const [h, setH] = useState(0);
  const [zoom, setZoom] = useState<number | null>(null); // null = Fit

  useLayoutEffect(() => {
    const box = boxRef.current;
    if (!box) return;
    const ro = new ResizeObserver(() => setAvail(box.clientWidth));
    ro.observe(box);
    setAvail(box.clientWidth);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    const el = receiptRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setH(el.offsetHeight));
    ro.observe(el);
    setH(el.offsetHeight);
    return () => ro.disconnect();
  }, [receiptRef]);

  const fit = Math.min(1, Math.max(MIN, (avail - 32) / RECEIPT_W));
  const scale = zoom ?? fit;
  const step = (d: number) => setZoom(Math.round(Math.min(MAX, Math.max(MIN, scale + d)) * 10) / 10);

  return (
    <div className="flex min-w-0 flex-col">
      <div role="toolbar" aria-label="Preview zoom (display only, does not change the receipt)" className="touch-ui flex items-center justify-center gap-1.5 border-b bg-card/80 px-3 py-2">
        <Button size="icon" variant="outline" className="h-9 w-9" aria-label="Zoom out preview" onClick={() => step(-STEP)} disabled={scale <= MIN}><Minus className="h-4 w-4" /></Button>
        <span aria-live="polite" aria-label={`Preview zoom ${Math.round(scale * 100)} percent`} className="w-14 text-center text-sm font-semibold tabular-nums">{Math.round(scale * 100)}%</span>
        <Button size="icon" variant="outline" className="h-9 w-9" aria-label="Zoom in preview" onClick={() => step(STEP)} disabled={scale >= MAX}><Plus className="h-4 w-4" /></Button>
        <Button variant={zoom === null ? 'secondary' : 'outline'} className="ml-1 h-9 gap-1.5" aria-label="Fit preview to screen" aria-pressed={zoom === null} onClick={() => setZoom(null)}><Maximize2 className="h-4 w-4" />Fit</Button>
      </div>
      <div ref={boxRef} className="overflow-x-auto overscroll-x-contain">
        <div className="mx-auto p-4" style={{ width: RECEIPT_W * scale + 32 }}>
          <div style={{ width: RECEIPT_W * scale, height: h ? h * scale : undefined }}>
            <div className="rounded-sm shadow-xl ring-1 ring-black/5" style={{ width: RECEIPT_W, transform: `scale(${scale})`, transformOrigin: 'top left' }}>
              {children(scale)}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

