import React, { useLayoutEffect, useRef, useState } from 'react';
import { type ReceiptData, type BrandingSettings, type TextElementId, mergeStyle, RECEIPT_W, RECEIPT_H, normalizeData, computeTotals, lineAmount, lineLabel, money } from '../types';

interface Props {
  data: ReceiptData;
  branding: BrandingSettings;
  receiptRef?: React.Ref<HTMLDivElement>;
  selectedElement?: TextElementId | null;
  onSelectElement?: (id: TextElementId) => void;
}

export default function ReceiptPreview({ data: rawData, branding, receiptRef, selectedElement, onSelectElement }: Props) {
  const data = normalizeData(rawData);
  const totals = computeTotals(data.items);
  const amt = money(totals.total);
  const multi = data.items.length > 1;
  // Fixed width, flexible height: content defines the height (minimum = reference RECEIPT_H).
  const innerRef = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState(RECEIPT_H);
  useLayoutEffect(() => {
    const el = innerRef.current;
    if (!el) return;
    const update = () => setHeight(Math.max(RECEIPT_H, Math.ceil(el.offsetHeight)));
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const wm = branding.watermark;
  const co = branding.company;
  const gs = branding.globalStyle;
  const ts = branding.textStyles;

  const s = (id: TextElementId, base?: React.CSSProperties): React.CSSProperties => {
    const custom = mergeStyle(gs, ts[id]);
    const ox = ts[id]?.offsetX ?? 0;
    const oy = ts[id]?.offsetY ?? 0;
    const result = { ...base, ...custom };
    if (ox || oy) { result.position = 'relative'; result.left = ox; result.top = oy; }
    return result;
  };

  // data-el marks each element for the editor's measuring / drag / alignment tools.
  // Selection outlines are drawn by the editor overlay (never inside the receipt itself).
  void selectedElement; void onSelectElement;
  const sel = (id: TextElementId): SelProps => ({ 'data-el': id, style: {} });

  const nameLines = co.name.split('\n');
  const addrLines = co.address.split('\n');

  // Center content area — matches reference proportions (not full-width)
  const CX = { paddingLeft: 60, paddingRight: 50 } as const;

  return (
    <div ref={receiptRef} id="receipt-canvas" style={{
      width: RECEIPT_W, height,
      fontFamily: gs.fontFamily || "Arial, Helvetica, 'Liberation Sans', sans-serif",
      fontSize: 12.5, lineHeight: 'normal', color: '#000', background: '#fff',
      position: 'relative', overflow: 'hidden', boxSizing: 'border-box',
    }}>
