/* ─── helpers ─── */

type SelProps = { 'data-el': string; style: React.CSSProperties };

function CRow({ id, label, valId, value, s, sel, bold, indent }: {
  id: TextElementId; label: string; valId: TextElementId; value: string;
  s: (id: TextElementId, base?: React.CSSProperties) => React.CSSProperties;
  sel: (id: TextElementId) => SelProps;
  bold?: boolean; indent?: number;
}) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
      <span {...sel(id)} style={{ ...s(id, { fontWeight: bold ? 700 : undefined, paddingLeft: indent }), ...sel(id).style }}>{label}</span>
      <span {...sel(valId)} style={{ ...s(valId, { fontWeight: bold ? 700 : undefined }), ...sel(valId).style }}>{value}</span>
    </div>
  );
}

function WatermarkLayer({ wm, height: H }: { wm: BrandingSettings['watermark']; height: number }) {
  if (!wm.url || wm.pattern === 'none') return null;

  const op = wm.opacity;
  const ox = wm.offsetX ?? 0, oy = wm.offsetY ?? 0;
  const rot = wm.rotation || 0;
  // Pattern layer is one selectable object in the editor (data-el), shared by preview/print/PNG/PDF.
  const layer: React.CSSProperties = { position: 'absolute', inset: 0, zIndex: 1, overflow: 'hidden', pointerEvents: 'none' };
  const iw = wm.width;
  const ih = wm.height;
  const count = wm.count || 12;

  // ── Custom layout: individual positioned items ──
  if (wm.layout === 'custom' && wm.customItems.length > 0) {
    return (
      <div style={{ position: 'absolute', inset: 0, zIndex: 1, overflow: 'hidden', pointerEvents: 'none' }}>
        {wm.customItems.map(c => (
          <img key={c.id} data-el={`wm:${c.id}`} src={wm.url} alt="" style={{
            position: 'absolute', left: c.x, top: c.y,
            width: c.width, height: c.height, opacity: c.opacity,
            transform: c.rotation ? `rotate(${c.rotation}deg)` : undefined,
            objectFit: 'contain', pointerEvents: 'none',
          }} />
        ))}
      </div>
    );
  }

  // ── Center: single logo ──
  if (wm.pattern === 'center') {
    return (
      <div data-el="watermark" style={{ ...layer, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <img src={wm.url} alt="" style={{ position: 'relative', left: ox, top: oy, width: iw, height: ih, opacity: op, objectFit: 'contain', pointerEvents: 'none', transform: rot ? `rotate(${-rot}deg)` : undefined }} />
      </div>
    );
  }

  // ── Single diagonal: one logo rotated ──
  if (wm.pattern === 'single-diagonal') {
    return (
      <div data-el="watermark" style={{ ...layer, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <img src={wm.url} alt="" style={{ position: 'relative', left: ox, top: oy, width: iw, height: ih, opacity: op, objectFit: 'contain', pointerEvents: 'none', transform: `rotate(${-rot}deg)` }} />
      </div>
    );
  }

  // ── Random layout: deterministic pseudo-random placement ──
  if (wm.layout === 'random') {
    const items: React.ReactNode[] = [];
    // Simple seeded random from count for determinism
    let seed = count * 7 + Math.round(iw) * 13 + Math.round(ih) * 17;
    const rng = () => { seed = (seed * 16807 + 0) % 2147483647; return (seed & 0x7fffffff) / 0x7fffffff; };
    for (let i = 0; i < count; i++) {
      const x = rng() * (RECEIPT_W - iw * 0.3) - iw * 0.15;
      const y = rng() * (H - ih * 0.3) - ih * 0.15;
      items.push(
        <img key={i} src={wm.url} alt="" style={{
          position: 'absolute', left: x + ox, top: y + oy,
          width: iw, height: ih, opacity: op,
          objectFit: 'contain', pointerEvents: 'none', transform: rot ? `rotate(${-rot}deg)` : undefined,
        }} />
      );
    }
    return (
      <div data-el="watermark" style={layer}>
        {items}
      </div>
    );
  }

  // ── Tiled patterns (grid / overlap) ──
  // Logos stay UPRIGHT. Alternating rows are offset horizontally
  // to create a staggered diagonal visual pattern.
  // Tiles fill the ENTIRE receipt — count is ignored for tiled modes
  // (it applies to random/custom only).
  let drawW = iw;
  let drawH = ih;
  let hs = wm.hSpacing;
  let vs = wm.vSpacing;

  if (wm.pattern === 'diagonal-dense') {
    drawW = iw * 0.6; drawH = ih * 0.6;
    hs = wm.hSpacing * 0.55; vs = wm.vSpacing * 0.55;
  } else if (wm.pattern === 'diagonal-spaced') {
    drawW = iw * 1.4; drawH = ih * 1.4;
    hs = wm.hSpacing * 1.6; vs = wm.vSpacing * 1.6;
  }

  let colStep = drawW + hs;
  let rowStep = drawH + vs;
  if (Math.abs(colStep) < 10) colStep = colStep < 0 ? -10 : 10;
  if (Math.abs(rowStep) < 10) rowStep = rowStep < 0 ? -10 : 10;
  const absCol = Math.abs(colStep);
  const absRow = Math.abs(rowStep);

  // Stagger amount — odd rows shift right to create diagonal visual
  const useStagger = wm.layout !== 'grid';
  const staggerAmt = wm.pattern === 'diagonal-alternating' ? absCol * 0.5 : absCol * 0.33;

  // Extend beyond receipt bounds so stagger doesn't leave gaps at edges
  const padX = absCol * 2;
  const cols = Math.ceil((RECEIPT_W + padX * 2) / absCol) + 1;
  const rows = Math.ceil((H + absRow * 3) / absRow) + 2;
  // Pattern offset wraps within one tile period so coverage never leaves gaps
  const wrap = (v: number, p: number) => ((v % p) + p) % p;
  const startX = -padX + wrap(ox, absCol * (useStagger ? 2 : 1)) - absCol;
  const startY = -absRow * 0.5 + wrap(oy, absRow * 2) - absRow * 2;

  const items: React.ReactNode[] = [];
  for (let r = 0; r < rows; r++) {
    const offset = (useStagger && r % 2 !== 0) ? staggerAmt : 0;
    for (let c = 0; c < cols + 2; c++) {
      const x = startX + c * absCol + offset;
      const y = startY + r * absRow;
      items.push(
        <img key={`${r}-${c}`} src={wm.url} alt="" style={{
          position: 'absolute', left: x, top: y,
          width: drawW, height: drawH, opacity: op,
          objectFit: 'contain', pointerEvents: 'none', transform: rot ? `rotate(${-rot}deg)` : undefined,
        }} />
      );
    }
  }

  return (
    <div data-el="watermark" style={layer}>
      {items}
    </div>
  );
}

function Divider({ mt }: { mt?: number }) {
  return <div style={{ borderTop: '2px solid #000', marginTop: mt ?? 0 }} />;
}

import { type TextStyle, type TextElementId, type BrandingSettings, TEXT_ELEMENT_LABELS, DEFAULT_GLOBAL_STYLE } from '../types';
import { Input } from '@project/components/ui/input';
import { Label } from '@project/components/ui/label';
import { Button } from '@project/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { ScrollArea } from '@project/components/ui/scroll-area';
import { RotateCcw, MousePointer2 } from 'lucide-react';
import { PanelHeader, Section } from './kit';

const FONT_OPTIONS = [
  "Arial, Helvetica, sans-serif",
  "'Times New Roman', Times, serif",
  "'Courier New', Courier, monospace",
  "Verdana, Geneva, sans-serif",
  "Georgia, serif",
  "Tahoma, Geneva, sans-serif",
  "'Trebuchet MS', sans-serif",
];

const ALL_ELEMENTS: TextElementId[] = Object.keys(TEXT_ELEMENT_LABELS) as TextElementId[];

interface Props {
  branding: BrandingSettings;
  onChange: (b: BrandingSettings) => void;
  selectedElement?: TextElementId | null;
  onSelectElement?: (id: TextElementId | null) => void;
}

export default function TypographyPanel({ branding, onChange, selectedElement, onSelectElement }: Props) {
  const selected = selectedElement ?? null;
  const isGlobal = !selected;

  const currentStyle = isGlobal
    ? branding.globalStyle
    : (branding.textStyles[selected!] ?? {});

  const updateStyle = (patch: Partial<TextStyle>) => {
    if (isGlobal) {
      onChange({ ...branding, globalStyle: { ...branding.globalStyle, ...patch } });
    } else {
      const ts = { ...branding.textStyles };
      ts[selected!] = { ...(ts[selected!] ?? {}), ...patch };
      onChange({ ...branding, textStyles: ts });
    }
  };

  const resetElement = () => {
    if (isGlobal) {
      onChange({ ...branding, globalStyle: DEFAULT_GLOBAL_STYLE });
    } else {
      const ts = { ...branding.textStyles };
      delete ts[selected!];
      onChange({ ...branding, textStyles: ts });
    }
  };

  const resetAll = () => {
    onChange({ ...branding, globalStyle: DEFAULT_GLOBAL_STYLE, textStyles: {} });
  };

  return (
    <div className="space-y-4">
      <PanelHeader title="Typography" description="Fine-tune receipt text. Changes affect the receipt only, never the app UI." action={
        <Button size="sm" variant="ghost" className="gap-1.5" onClick={resetAll}><RotateCcw className="h-4 w-4" /> Reset all</Button>
      } />

      <div className="rounded-lg border border-dashed p-3 flex items-center gap-2 text-xs text-muted-foreground bg-card">
        <MousePointer2 className="w-4 h-4 shrink-0" />
        <span>Click any text element on the receipt to select and edit it.</span>
      </div>

      {/* Element selector */}
      <div>
        <Label className="text-sm font-medium mb-1.5 block">Selected Element</Label>
        <Select value={selected ?? 'global'} onValueChange={v => {
          if (v === 'global') onSelectElement?.(null);
          else onSelectElement?.(v as TextElementId);
        }}>
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            <ScrollArea className="h-64">
              <SelectItem value="global">🌐 Global Default</SelectItem>
              {ALL_ELEMENTS.map(id => (
                <SelectItem key={id} value={id}>
                  {branding.textStyles[id] ? '✏️ ' : ''}{TEXT_ELEMENT_LABELS[id]}
                </SelectItem>
              ))}
            </ScrollArea>
          </SelectContent>
        </Select>
      </div>

      {selected && (
        <div className="text-sm text-accent-foreground font-medium bg-accent rounded-md px-3 py-1.5">
          Editing: {TEXT_ELEMENT_LABELS[selected]}
        </div>
      )}

      <Section title="Style">
        <div>
          <Label className="text-sm font-medium mb-1.5 block">Font Family</Label>
          <Select value={currentStyle.fontFamily ?? ''} onValueChange={v => updateStyle({ fontFamily: v || undefined })}>
            <SelectTrigger><SelectValue placeholder="Inherit" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="inherit">Inherit (Default)</SelectItem>
              {FONT_OPTIONS.map(f => <SelectItem key={f} value={f}>{f.split(',')[0].replace(/'/g, '')}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        <div className="grid grid-cols-2 gap-2">
          <Num label="Font Size (px)" value={currentStyle.fontSize} onChange={v => updateStyle({ fontSize: v || undefined })} placeholder="Inherit" />
          <div>
            <Label className="text-sm font-medium mb-1.5 block">Font Weight</Label>
            <Select value={String(currentStyle.fontWeight ?? '')} onValueChange={v => updateStyle({ fontWeight: v ? Number(v) : undefined })}>
              <SelectTrigger><SelectValue placeholder="Inherit" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="inherit">Inherit</SelectItem>
                <SelectItem value="400">Normal (400)</SelectItem>
                <SelectItem value="700">Bold (700)</SelectItem>
                <SelectItem value="300">Light (300)</SelectItem>
                <SelectItem value="500">Medium (500)</SelectItem>
                <SelectItem value="600">Semi-Bold (600)</SelectItem>
                <SelectItem value="900">Black (900)</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-2">
          <Num label="Letter Spacing" value={currentStyle.letterSpacing} onChange={v => updateStyle({ letterSpacing: v })} step={0.1} placeholder="Inherit" />
          <Num label="Line Height" value={currentStyle.lineHeight} onChange={v => updateStyle({ lineHeight: v })} step={0.1} placeholder="Inherit" />
        </div>

        <div>
          <Label className="text-sm font-medium mb-1.5 block">Font Style</Label>
          <Select value={currentStyle.fontStyle ?? 'normal'} onValueChange={v => updateStyle({ fontStyle: v === 'normal' ? undefined : v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="normal">Normal</SelectItem>
              <SelectItem value="italic">Italic</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {!isGlobal && (
          <>
            <div className="grid grid-cols-2 gap-2">
              <Num label="X Offset (px)" value={currentStyle.offsetX} onChange={v => updateStyle({ offsetX: v })} placeholder="0" />
              <Num label="Y Offset (px)" value={currentStyle.offsetY} onChange={v => updateStyle({ offsetY: v })} placeholder="0" />
            </div>
          </>
        )}

        <Button variant="outline" className="w-full gap-2" onClick={resetElement}>
          <RotateCcw className="h-4 w-4" />
          Reset {isGlobal ? 'Global' : TEXT_ELEMENT_LABELS[selected!]} to Master
        </Button>
      </Section>
    </div>
  );
}

function Num({ label, value, onChange, step, placeholder }: {
  label: string; value?: number; onChange: (v: number | undefined) => void; step?: number; placeholder?: string;
}) {
  return (
    <div>
      <Label className="text-sm font-medium mb-1.5 block">{label}</Label>
      <Input
        type="number"
        value={value ?? ''}
        onChange={e => onChange(e.target.value ? Number(e.target.value) : undefined)}
        step={step}
        placeholder={placeholder}

      />
    </div>
  );
}

import { useState } from 'react';
import {
  type WatermarkSettings, type WatermarkPattern, type WatermarkLayout, type CustomWatermark,
  WATERMARK_PATTERN_LABELS, WATERMARK_LAYOUT_LABELS, DEFAULT_WATERMARK, RECEIPT_W, RECEIPT_H,
} from '../types';
import { Button } from '@project/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@project/components/ui/collapsible';
import { toast } from 'sonner';
import { RotateCcw, ChevronDown, Plus, Copy, Trash2 } from 'lucide-react';
import { Section, Field, SliderField } from './kit';
import { ImagePicker } from './LogoEditor';

const PATTERNS: WatermarkPattern[] = ['diagonal-repeated', 'diagonal-dense', 'diagonal-spaced', 'diagonal-alternating', 'single-diagonal', 'center', 'none'];
const LAYOUTS = Object.keys(WATERMARK_LAYOUT_LABELS) as WatermarkLayout[];

export default function WatermarkEditor({ watermark: wm, onChange }: { watermark: WatermarkSettings; onChange: (w: WatermarkSettings) => void }) {
  const set = (patch: Partial<WatermarkSettings>) => onChange({ ...wm, ...patch });
  const none = wm.pattern === 'none';
  const single = wm.pattern === 'single-diagonal' || wm.pattern === 'center';
  const custom = wm.layout === 'custom' && !single;
  const ratio = wm.height ? wm.width / wm.height : 1;

  return (
    <div className="space-y-4">
      <Section title="Pattern">
        <Field label="Preset">
          <Select value={wm.pattern} onValueChange={v => set({ pattern: v as WatermarkPattern })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{PATTERNS.map(p => <SelectItem key={p} value={p}>{WATERMARK_PATTERN_LABELS[p]}</SelectItem>)}</SelectContent>
          </Select>
        </Field>
        {!none && <ImagePicker url={wm.url} label="Watermark" onChange={url => set({ url })} />}
      </Section>

      {!none && !custom && (
        <>
          <Section title="Appearance">
            <SliderField label="Opacity" value={Math.round(wm.opacity * 100)} min={0} max={100} unit="%" onChange={v => set({ opacity: v / 100 })} />
            <SliderField label="Logo size" value={wm.width} min={20} max={500} unit="px" onChange={w => set({ width: w, height: Math.round(w / ratio) })} />
            <SliderField label="Rotation" value={wm.rotation} min={-180} max={180} unit="°" onChange={rotation => set({ rotation })} />
          </Section>
          <Section title="Spacing & offset">
            {!single && <SliderField label="Horizontal spacing" value={wm.hSpacing} min={-100} max={500} unit="px" onChange={hSpacing => set({ hSpacing })} />}
            {!single && <SliderField label="Vertical spacing" value={wm.vSpacing} min={-40} max={400} unit="px" onChange={vSpacing => set({ vSpacing })} />}
            <SliderField label="Offset X" value={wm.offsetX ?? 0} min={-RECEIPT_W / 2} max={RECEIPT_W / 2} unit="px" onChange={offsetX => set({ offsetX })} />
            <SliderField label="Offset Y" value={wm.offsetY ?? 0} min={-RECEIPT_H / 2} max={RECEIPT_H / 2} unit="px" onChange={offsetY => set({ offsetY })} />
          </Section>
        </>
      )}

      {!none && !single && <AdvancedLayout wm={wm} set={set} />}

      <Button variant="outline" className="w-full gap-2" onClick={() => { onChange({ ...DEFAULT_WATERMARK }); toast('Watermark reset'); }}>
        <RotateCcw className="h-4 w-4" /> Reset Watermark
      </Button>
    </div>
  );
}

function AdvancedLayout({ wm, set }: { wm: WatermarkSettings; set: (p: Partial<WatermarkSettings>) => void }) {
  const [open, setOpen] = useState(wm.layout !== 'grid');
  const [sel, setSel] = useState<string | null>(null);
  const items = wm.customItems;
  const update = (id: string, p: Partial<CustomWatermark>) => set({ customItems: items.map(c => c.id === id ? { ...c, ...p } : c) });
  const add = () => {
    const it: CustomWatermark = { id: crypto.randomUUID(), x: RECEIPT_W / 2 - 90, y: RECEIPT_H / 2 - 25, width: wm.width, height: wm.height, rotation: 0, opacity: wm.opacity };
    set({ customItems: [...items, it] }); setSel(it.id);
  };
  const selItem = items.find(c => c.id === sel);
  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-lg border bg-card shadow-xs">
      <CollapsibleTrigger className="flex w-full items-center justify-between p-4 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
        Advanced layout <ChevronDown className={`h-4 w-4 transition-transform ${open ? 'rotate-180' : ''}`} />
      </CollapsibleTrigger>
      <CollapsibleContent className="space-y-3 px-4 pb-4">
        <Field label="Layout mode" hint="Grid and Overlap tile the pattern; Random scatters logos; Custom lets you place each logo.">
          <Select value={wm.layout} onValueChange={v => set({ layout: v as WatermarkLayout })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{LAYOUTS.map(l => <SelectItem key={l} value={l}>{WATERMARK_LAYOUT_LABELS[l]}</SelectItem>)}</SelectContent>
          </Select>
        </Field>
        {wm.layout === 'random' && <SliderField label="Number of logos" value={wm.count} min={1} max={60} onChange={count => set({ count })} />}
        {wm.layout === 'custom' && (
          <div className="space-y-3">
            <Button variant="outline" className="w-full gap-2" onClick={add}><Plus className="h-4 w-4" /> Add watermark logo</Button>
            {items.map((c, i) => (
              <div key={c.id} onClick={() => setSel(c.id)}
                className={`flex cursor-pointer items-center gap-2 rounded-md border px-3 py-2 text-sm ${sel === c.id ? 'border-primary bg-accent' : 'hover:bg-muted'}`}>
                <span className="flex-1">Logo {i + 1}</span>
                <Button size="icon" variant="ghost" className="h-7 w-7" aria-label="Duplicate" onClick={e => { e.stopPropagation(); const d = { ...c, id: crypto.randomUUID(), x: c.x + 20, y: c.y + 20 }; set({ customItems: [...items, d] }); setSel(d.id); }}><Copy className="h-4 w-4" /></Button>
                <Button size="icon" variant="ghost" className="h-7 w-7 text-destructive" aria-label="Remove" onClick={e => { e.stopPropagation(); set({ customItems: items.filter(x => x.id !== c.id) }); }}><Trash2 className="h-4 w-4" /></Button>
              </div>
            ))}
            {selItem && (
              <div className="space-y-3 border-t pt-3">
                <SliderField label="Size" value={selItem.width} min={10} max={500} unit="px" onChange={w => update(selItem.id, { width: w, height: Math.round(w * selItem.height / selItem.width) })} />
                <SliderField label="Opacity" value={Math.round(selItem.opacity * 100)} min={0} max={100} unit="%" onChange={v => update(selItem.id, { opacity: v / 100 })} />
                <SliderField label="Rotation" value={selItem.rotation} min={-180} max={180} unit="°" onChange={rotation => update(selItem.id, { rotation })} />
                <p className="text-xs text-muted-foreground">Tip: drag logos directly on the receipt to place them.</p>
              </div>
            )}
          </div>
        )}
      </CollapsibleContent>
    </Collapsible>
  );
}

