/** Label is programmatically tied to its control; errors are announced and linked via aria-describedby. */
export function Field({ label, error, hint, required, children, className }: { label: string; error?: string; hint?: string; required?: boolean; children: React.ReactElement; className?: string }) {
  const id = useId();
  const msgId = `${id}-msg`;
  const msg = error || hint;
  const child = cloneElement(children as React.ReactElement<Record<string, unknown>>, {
    id, 'aria-invalid': error ? true : undefined, 'aria-required': required || undefined,
    'aria-describedby': msg ? msgId : undefined, 'aria-label': (children.props as { 'aria-label'?: string })['aria-label'] ?? label,
  });
  return (
    <div className={cn('space-y-1.5', className)}>
      <Label htmlFor={id} className="text-sm font-medium">
        {label}{required && <span className="text-destructive" aria-hidden> *</span>}
      </Label>
      {child}
      {error
        ? <p id={msgId} role="alert" className="flex items-center gap-1 text-xs font-medium text-destructive"><AlertCircle className="h-3.5 w-3.5 shrink-0" aria-hidden />{error}</p>
        : hint ? <p id={msgId} className="text-xs text-muted-foreground">{hint}</p> : null}
    </div>
  );
}

export function SliderField({ label, value, min, max, step = 1, unit = '', onChange, format }: {
  label: string; value: number; min: number; max: number; step?: number; unit?: string;
  onChange: (v: number) => void; format?: (v: number) => string;
}) {
  const clamp = (v: number) => Math.min(max, Math.max(min, Math.round(v / step) * step));
  const text = format ? format(value) : `${Math.round(value * 100) / 100}${unit}`;
  return (
    <div className="space-y-2" role="group" aria-label={label}>
      <div className="flex items-center justify-between gap-2">
        <Label className="text-sm font-medium">{label}</Label>
        <div className="flex items-center gap-1">
          <Input type="number" inputMode="decimal" value={Math.round(value * 100) / 100} step={step} min={min} max={max}
            onChange={e => onChange(Number(e.target.value) || 0)}
            className="h-8 w-16 px-2 text-right text-xs tabular-nums" aria-label={`${label} value${unit ? ` (${unit})` : ''}`} />
          {unit && <span className="w-3 text-xs text-muted-foreground" aria-hidden>{unit}</span>}
        </div>
      </div>
      <div className="flex items-center gap-2">
        <Button type="button" size="icon" variant="outline" className="h-9 w-9 shrink-0" aria-label={`Decrease ${label}`} disabled={value <= min} onClick={() => onChange(clamp(value - step))}><Minus className="h-4 w-4" /></Button>
        <Slider min={min} max={max} step={step} value={[value]} onValueChange={([v]) => onChange(v)} aria-label={label} aria-valuetext={text} className="flex-1 py-2" />
        <Button type="button" size="icon" variant="outline" className="h-9 w-9 shrink-0" aria-label={`Increase ${label}`} disabled={value >= max} onClick={() => onChange(clamp(value + step))}><Plus className="h-4 w-4" /></Button>
      </div>
    </div>
  );
}

export function SegmentedControl<T extends string>({ value, options, onChange }: { value: T; options: { value: T; label: string; icon?: React.ReactNode }[]; onChange: (v: T) => void }) {
  return (
    <div role="group" className="grid rounded-lg bg-muted p-1" style={{ gridTemplateColumns: `repeat(${options.length}, 1fr)` }}>
      {options.map(o => (
        <button key={o.value} type="button" aria-pressed={value === o.value} onClick={() => onChange(o.value)}
          className={cn('flex min-h-9 items-center justify-center gap-1.5 rounded-md text-sm font-medium transition-colors [&_svg]:h-4 [&_svg]:w-4',
            value === o.value ? 'bg-card text-foreground shadow-xs ring-1 ring-primary/40 font-semibold' : 'text-muted-foreground hover:text-foreground')}>
          {o.icon}{o.label}
        </button>
      ))}
    </div>
  );
}

import { PDFDocument, StandardFonts, rgb, degrees, pushGraphicsState, popGraphicsState, setCharacterSpacing, type PDFFont, type PDFImage } from 'pdf-lib';
import { fetchImage } from 'zitejs/api';
import { RECEIPT_W } from './types';

/**
 * ONE canonical receipt (the editor's #receipt-canvas DOM) → ONE display list → PNG / PDF.
 * Print renders the very same prepared clone. Geometry is RECEIPT_W × content height in CSS px,
 * mounted in an isolated fixed-width frame so screen size, zoom and DPR never matter.
 */

/* ─── Assets: each unique image fetched once, inlined, downscaled if oversized ─── */

type Asset = { dataUrl: string; bytes: Uint8Array; type: 'png' | 'jpg'; img: HTMLImageElement };
const assetCache = new Map<string, Promise<Asset>>();
const MAX_ASSET_PX = 1200;

const blobToDataUrl = (b: Blob) => new Promise<string>((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result as string); r.onerror = rej; r.readAsDataURL(b); });
const loadImg = async (src: string) => { const i = new Image(); i.src = src; await i.decode(); return i; };

async function rawDataUrl(src: string) {
  if (src.startsWith('data:')) return src;
  try {
    const r = await fetch(src, { mode: 'cors' });
    if (!r.ok) throw new Error(String(r.status));
    return await blobToDataUrl(await r.blob());
  } catch {
    // Host blocks cross-origin reads → fetch through the app's backend.
    return (await fetchImage({ url: src })).dataUrl;
  }
}

async function buildAsset(src: string): Promise<Asset> {
  let dataUrl = await rawDataUrl(src);
  let img = await loadImg(dataUrl);
  const isJpg = /^data:image\/jpe?g/i.test(dataUrl), isPng = /^data:image\/png/i.test(dataUrl);
  const nw = img.naturalWidth || 512, nh = img.naturalHeight || 512;
  const big = Math.max(nw, nh) > MAX_ASSET_PX;
  if (big || (!isPng && !isJpg) || !dataUrl.includes(';base64,')) {
    const k = big ? MAX_ASSET_PX / Math.max(nw, nh) : 1;
    const c = document.createElement('canvas');
    c.width = Math.round(nw * k); c.height = Math.round(nh * k);
    c.getContext('2d')!.drawImage(img, 0, 0, c.width, c.height);
    dataUrl = c.toDataURL(isJpg ? 'image/jpeg' : 'image/png', 0.9);
    img = await loadImg(dataUrl);
  }
  const bytes = Uint8Array.from(atob(dataUrl.split(',')[1]), ch => ch.charCodeAt(0));
  return { dataUrl, bytes, type: /^data:image\/jpe?g/i.test(dataUrl) ? 'jpg' : 'png', img };
}

async function getAsset(src: string) {
  for (let attempt = 0; attempt < 2; attempt++) {
    if (!assetCache.has(src)) assetCache.set(src, buildAsset(src));
    try { return await assetCache.get(src)!; } catch { assetCache.delete(src); }
  }
  throw new Error('The logo or watermark image could not be loaded. Please try again.');
}

/* ─── Prepare: wait for fonts + assets, clone the canonical receipt with inlined images ─── */

async function prepare(el: HTMLElement) {
  await document.fonts.ready;
  const imgs = Array.from(el.querySelectorAll('img'));
  const srcs = [...new Set(imgs.map(i => i.getAttribute('src') || '').filter(Boolean))];
  const bySrc = new Map(await Promise.all(srcs.map(async s => [s, await getAsset(s)] as const)));
  const byData = new Map([...bySrc.values()].map(a => [a.dataUrl, a]));
  const clone = el.cloneNode(true) as HTMLElement;
  clone.querySelectorAll('img').forEach(i => { const a = bySrc.get(i.getAttribute('src') || ''); if (a) i.setAttribute('src', a.dataUrl); });
  clone.style.transform = 'none';
  return { clone, byData, height: Math.ceil(el.offsetHeight) };
}

const BASE_CSS = `* { margin: 0; padding: 0; box-sizing: border-box; }`;
function fontFaceCss() {
  let css = '';
  for (const sheet of Array.from(document.styleSheets)) {
    try { for (const rule of Array.from(sheet.cssRules)) if (rule instanceof CSSFontFaceRule) css += rule.cssText + '\n'; } catch { /* cross-origin */ }
  }
  return css;
}

async function mount(el: HTMLElement) {
  const { clone, byData, height } = await prepare(el);
  const frame = document.createElement('iframe');
  frame.setAttribute('aria-hidden', 'true');
  frame.style.cssText = `position:fixed;left:-10000px;top:0;width:${RECEIPT_W}px;height:${height}px;border:0;visibility:hidden;`;
  document.body.appendChild(frame);
  const d = frame.contentDocument!;
  d.open();
  d.write(`<!DOCTYPE html><html><head><style>${BASE_CSS}\n${fontFaceCss()}\nhtml,body{width:${RECEIPT_W}px;height:${height}px;overflow:hidden;}</style></head><body></body></html>`);
  d.close();
  const root = d.importNode(clone, true) as HTMLElement;
  d.body.appendChild(root);
  await d.fonts?.ready;
  await Promise.all(Array.from(d.images).map(i => i.decode().catch(() => undefined)));
  return { root, win: frame.contentWindow!, byData, height, cleanup: () => frame.remove() };
}

/* ─── Display list: every visible layer of the canonical receipt, in paint order ─── */

type RGBA = { r: number; g: number; b: number; a: number };
type Op =
  | { k: 'rect'; x: number; y: number; w: number; h: number; c: RGBA; op: number }
  | { k: 'img'; asset: Asset; cx: number; cy: number; w: number; h: number; rot: number; op: number; logo: boolean }
  | { k: 'text'; s: string; x: number; y: number; size: number; family: string; weight: string; style: string; c: RGBA; op: number; ls: number };

function parseColor(c: string): RGBA {
  const m = c.match(/rgba?\(([^)]+)\)/);
  if (!m) return { r: 0, g: 0, b: 0, a: 1 };
  const [r, g, b, a] = m[1].split(/[ ,/]+/).filter(Boolean).map(Number);
  return { r: r / 255, g: g / 255, b: b / 255, a: a ?? 1 };
}

const metricsCtx = document.createElement('canvas').getContext('2d')!;

function collect(root: HTMLElement, win: Window, byData: Map<string, Asset>, H: number) {
  const gcs = (n: Element) => win.getComputedStyle(n);
  const origin = root.getBoundingClientRect();
  const box = (r: DOMRect) => ({ x: r.left - origin.left, y: r.top - origin.top, w: r.width, h: r.height });
  const opacity = (n: Element) => { let o = 1; for (let e: Element | null = n; e && e !== root.parentElement; e = e.parentElement) o *= parseFloat(gcs(e).opacity || '1'); return o; };
  const hidden = (n: Element) => { const cs = gcs(n); return cs.display === 'none' || cs.visibility === 'hidden'; };
  const ops: Op[] = [];
  const bg = parseColor(gcs(root).backgroundColor);

  const walker = root.ownerDocument.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
  for (let n: Node | null = walker.currentNode; n; n = walker.nextNode()) {
    if (n.nodeType === Node.TEXT_NODE) text(n as Text);
    else if ((n as Element).tagName === 'IMG') image(n as HTMLImageElement);
    else borders(n as HTMLElement);
  }

  function borders(node: HTMLElement) {
    if (hidden(node)) return;
    const cs = gcs(node), b = box(node.getBoundingClientRect()), op = opacity(node);
    const t = parseFloat(cs.borderTopWidth), bo = parseFloat(cs.borderBottomWidth), l = parseFloat(cs.borderLeftWidth), r = parseFloat(cs.borderRightWidth);
    if (t && cs.borderTopStyle !== 'none') ops.push({ k: 'rect', x: b.x, y: b.y, w: b.w, h: t, c: parseColor(cs.borderTopColor), op });
    if (bo && cs.borderBottomStyle !== 'none') ops.push({ k: 'rect', x: b.x, y: b.y + b.h - bo, w: b.w, h: bo, c: parseColor(cs.borderBottomColor), op });
    if (l && cs.borderLeftStyle !== 'none') ops.push({ k: 'rect', x: b.x, y: b.y, w: l, h: b.h, c: parseColor(cs.borderLeftColor), op });
    if (r && cs.borderRightStyle !== 'none') ops.push({ k: 'rect', x: b.x + b.w - r, y: b.y, w: r, h: b.h, c: parseColor(cs.borderRightColor), op });
  }

  function image(img: HTMLImageElement) {
    const asset = byData.get(img.getAttribute('src') || '');
    if (!asset || hidden(img)) return;
    const r = box(img.getBoundingClientRect());
    if (r.x > RECEIPT_W || r.y > H || r.x + r.w < 0 || r.y + r.h < 0) return;
    // Layout box (pre-transform) + object-fit: contain, exactly like the browser.
    const nw = asset.img.naturalWidth || 1, nh = asset.img.naturalHeight || 1;
    const s = Math.min(img.offsetWidth / nw, img.offsetHeight / nh);
    const rot = parseFloat(img.style.transform.match(/rotate\(([-\d.]+)deg\)/)?.[1] ?? '0');
    ops.push({ k: 'img', asset, cx: r.x + r.w / 2, cy: r.y + r.h / 2, w: nw * s, h: nh * s, rot, op: opacity(img), logo: img.dataset.el === 'logo' });
  }

  function text(t: Text) {
    const parent = t.parentElement;
    if (!parent || !t.data.trim() || hidden(parent)) return;
    const cs = gcs(parent);
    const size = parseFloat(cs.fontSize);
    metricsCtx.font = `${cs.fontStyle} ${cs.fontWeight} ${size}px ${cs.fontFamily}`;
    const m = metricsCtx.measureText('Hg');
    const asc = m.fontBoundingBoxAscent, desc = m.fontBoundingBoxDescent;
    const c = parseColor(cs.color), op = opacity(parent);
    const ls = cs.letterSpacing === 'normal' ? 0 : parseFloat(cs.letterSpacing) || 0;
    const range = root.ownerDocument.createRange();
    const re = /\S+/g;
    let mm: RegExpExecArray | null;
    while ((mm = re.exec(t.data))) {
      range.setStart(t, mm.index); range.setEnd(t, mm.index + mm[0].length);
      const rect = range.getClientRects()[0];
      if (!rect) continue;
      const b = box(rect);
      ops.push({ k: 'text', s: mm[0], x: b.x, y: b.y + (b.h - (asc + desc)) / 2 + asc, size, family: cs.fontFamily, weight: cs.fontWeight, style: cs.fontStyle, c, op, ls });
    }
  }

  validate(root, ops);
  return { ops, bg };
}

/** Refuse to produce an incomplete export. */
function validate(root: HTMLElement, ops: Op[]) {
  const imgs = ops.filter(o => o.k === 'img');
  if (root.querySelector('img[data-el="logo"]') && !imgs.some(o => o.k === 'img' && o.logo)) throw new Error('Logo did not render — export cancelled.');
  const wmCount = root.querySelectorAll('[data-el="watermark"] img, img[data-el^="wm:"]').length;
  if (wmCount && imgs.filter(o => o.k === 'img' && !o.logo).length === 0) throw new Error('Watermark did not render — export cancelled.');
  const all = ops.filter(o => o.k === 'text').map(o => (o as { s: string }).s).join(' ');
  for (const need of ['Transaction', 'Total:', 'Thank', 'Cashier\'s', 'INPUT']) {
    if (!all.includes(need)) throw new Error('Receipt content did not fully render — export cancelled.');
  }
}

/* ─── PRINT: the same prepared clone, page = receipt size ─── */

export async function printReceipt(el: HTMLElement) {
  const { clone, height } = await prepare(el);
  const w = window.open('', '_blank');
  if (!w) return;
  w.document.write(`<!DOCTYPE html><html><head><style>
    ${fontFaceCss()}
    @page { margin: 0; size: ${RECEIPT_W}px ${height}px; }
    ${BASE_CSS}
    html, body { width: ${RECEIPT_W}px; height: ${height}px; overflow: hidden; }
  </style></head><body></body></html>`);
  w.document.body.appendChild(w.document.importNode(clone, true));
  w.document.close();
  await Promise.all(Array.from(w.document.images).map(i => i.decode().catch(() => undefined)));
  await w.document.fonts?.ready;
  w.focus();
  w.print();
  setTimeout(() => w.close(), 1000);
}

/* ─── PNG: display list painted onto a canvas (fixed 2× resolution, independent of device) ─── */

export async function captureReceiptPng(el: HTMLElement, scale = 2): Promise<Blob> {
  const { root, win, byData, height: H, cleanup } = await mount(el);
  try {
    const { ops, bg } = collect(root, win, byData, H);
    scale = Math.min(scale, Math.sqrt(16_000_000 / (RECEIPT_W * H)), 16_000 / H);
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(RECEIPT_W * scale);
    canvas.height = Math.round(H * scale);
    const ctx = canvas.getContext('2d')! as CanvasRenderingContext2D & { letterSpacing?: string };
    ctx.scale(scale, scale);
    ctx.fillStyle = `rgb(${bg.r * 255},${bg.g * 255},${bg.b * 255})`;
    ctx.fillRect(0, 0, RECEIPT_W, H);
    const css = (c: RGBA) => `rgba(${c.r * 255},${c.g * 255},${c.b * 255},${c.a})`;
    for (const o of ops) {
      ctx.save();
      ctx.globalAlpha = o.op;
      if (o.k === 'rect') { ctx.fillStyle = css(o.c); ctx.fillRect(o.x, o.y, o.w, o.h); }
      else if (o.k === 'img') { ctx.translate(o.cx, o.cy); ctx.rotate((o.rot * Math.PI) / 180); ctx.drawImage(o.asset.img, -o.w / 2, -o.h / 2, o.w, o.h); }
      else {
        ctx.font = `${o.style} ${o.weight} ${o.size}px ${o.family}`;
        ctx.letterSpacing = `${o.ls}px`;
        ctx.textBaseline = 'alphabetic';
        ctx.fillStyle = css(o.c);
        ctx.fillText(o.s, o.x, o.y);
      }
      ctx.restore();
    }
    return await new Promise((res, rej) => canvas.toBlob(b => b ? res(b) : rej(new Error('PNG encode failed')), 'image/png'));
  } finally { cleanup(); }
}

/* ─── PDF: same display list, vector text/lines, each image embedded once ─── */

const PT = 0.75; // 1 CSS px = 0.75 pt, same as Print → PDF

function pdfFontName(family: string, bold: boolean, italic: boolean): StandardFonts {
  const f = family.toLowerCase();
  const first = f.split(',')[0];
  const key = /courier|mono/.test(f) ? 'C' : /times|georgia|garamond|serif/.test(first) && !/sans/.test(first) ? 'T' : 'H';
  const table = {
    H: [StandardFonts.Helvetica, StandardFonts.HelveticaBold, StandardFonts.HelveticaOblique, StandardFonts.HelveticaBoldOblique],
    T: [StandardFonts.TimesRoman, StandardFonts.TimesRomanBold, StandardFonts.TimesRomanItalic, StandardFonts.TimesRomanBoldItalic],
    C: [StandardFonts.Courier, StandardFonts.CourierBold, StandardFonts.CourierOblique, StandardFonts.CourierBoldOblique],
  } as const;
  return table[key][(bold ? 1 : 0) + (italic ? 2 : 0)];
}

export async function captureReceiptPdf(el: HTMLElement, filename: string) {
  const blob = await renderReceiptPdf(el);
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/** The canonical PDF — used by Download PDF and the email attachment alike. */
export async function renderReceiptPdf(el: HTMLElement): Promise<Blob> {
  const { root, win, byData, height: H, cleanup } = await mount(el);
  try {
    const { ops, bg } = collect(root, win, byData, H);
    const doc = await PDFDocument.create();
    const page = doc.addPage([RECEIPT_W * PT, H * PT]);
    const X = (px: number) => px * PT;
    const Y = (px: number) => (H - px) * PT;
    const fonts = new Map<string, PDFFont>();
    const images = new Map<Asset, PDFImage>();
    page.drawRectangle({ x: 0, y: 0, width: X(RECEIPT_W), height: H * PT, color: rgb(bg.r, bg.g, bg.b) });

    for (const o of ops) {
      if (o.k === 'rect') {
        page.drawRectangle({ x: X(o.x), y: Y(o.y + o.h), width: o.w * PT, height: o.h * PT, color: rgb(o.c.r, o.c.g, o.c.b), opacity: o.c.a * o.op });
      } else if (o.k === 'img') {
        let pi = images.get(o.asset);
        if (!pi) { pi = o.asset.type === 'png' ? await doc.embedPng(o.asset.bytes) : await doc.embedJpg(o.asset.bytes); images.set(o.asset, pi); }
        const a = (-o.rot * Math.PI) / 180, hw = (o.w / 2) * PT, hh = (o.h / 2) * PT;
        page.drawImage(pi, {
          x: X(o.cx) - (Math.cos(a) * hw - Math.sin(a) * hh),
          y: Y(o.cy) - (Math.sin(a) * hw + Math.cos(a) * hh),
          width: o.w * PT, height: o.h * PT, rotate: degrees(-o.rot), opacity: o.op,
        });
      } else {
        const name = pdfFontName(o.family, parseInt(o.weight) >= 600 || o.weight === 'bold', o.style !== 'normal');
        let font = fonts.get(name);
        if (!font) { font = await doc.embedFont(name); fonts.set(name, font); }
        let s = o.s;
        try { font.encodeText(s); } catch { s = Array.from(s).map(ch => { try { font!.encodeText(ch); return ch; } catch { return '?'; } }).join(''); }
        if (o.ls) page.pushOperators(pushGraphicsState(), setCharacterSpacing(o.ls * PT));
        page.drawText(s, { x: X(o.x), y: Y(o.y), size: o.size * PT, font, color: rgb(o.c.r, o.c.g, o.c.b), opacity: o.c.a * o.op });
        if (o.ls) page.pushOperators(popGraphicsState());
      }
    }

    const bytes = await doc.save({ useObjectStreams: true });
    return new Blob([bytes as BlobPart], { type: 'application/pdf' });
  } finally { cleanup(); }
}

