@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-size: var(--font-size-md);
    line-height: var(--line-height);
  }
  /* Form controls inherit the single UI font (browsers otherwise use their own) */
  button, input, select, textarea { font-family: inherit; }
  input::placeholder, textarea::placeholder { color: hsl(var(--muted-foreground) / 0.7); }
  html, body { overflow-x: hidden; max-width: 100%; }
  /* Always-visible keyboard focus for the app UI */
  .touch-ui :focus-visible, [role="dialog"] :focus-visible, header :focus-visible {
    outline: 2px solid hsl(var(--ring)); outline-offset: 2px; border-radius: 6px;
  }
  .touch-ui button:active:not(:disabled) { transform: translateY(1px); }
  button:disabled, input:disabled { cursor: not-allowed; }
  [aria-invalid="true"] { border-color: hsl(var(--destructive)) !important; box-shadow: 0 0 0 1px hsl(var(--destructive)); }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
  }
}

/* Touch devices: comfortable 44px targets for the APP UI only (never the receipt canvas). */
@media (pointer: coarse) {
  .touch-ui button:not([role="switch"]):not([role="checkbox"]):not([role="radio"]),
  .touch-ui input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
  .touch-ui [role="combobox"] { min-height: 44px; }
  .touch-ui button.size-auto { min-height: 0; }
  .touch-ui [role="slider"] { height: 28px; width: 28px; }
  .touch-ui button + button { margin-left: 0; }
  /* 16px stops iOS from zooming the page when a field is focused */
  .touch-ui input, .touch-ui textarea, .touch-ui [role="combobox"] { font-size: 16px; }
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import './index.css';
import App from "./App";
import { ErrorBoundary } from 'react-error-boundary';
import { HammerIcon } from 'lucide-react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const queryClient = new QueryClient();

function reloadApp() {
  if (window._ziteOnReload) {
    window._ziteOnReload();
  } else {
    location.reload();
  }
}

function RuntimeErrorFallback(props: { error: Error }) {
  const allowAiFix = window.__ziteAllowAiFix === true;

  return (
    <div className="fixed inset-0 grid place-items-center">
      <div className="relative w-full max-w-xl rounded border-t-4 border-t-red-500 bg-white p-4 shadow-lg">
        <h3 className="mb-2 flex items-center gap-2 font-medium">
          Issue rendering app
        </h3>
        <p className="mb-4 text-sm text-gray-600">
          {allowAiFix
            ? 'Try asking Zite to fix the issue or find a workaround.'
            : 'Something went wrong while loading this app. You can try reloading the page.'}
        </p>

        <pre className="overflow-auto rounded border-l-4 border-red-500 bg-red-50 p-4 font-mono text-sm text-red-900">
          {props.error.message}
        </pre>
        <div className="mt-4 flex gap-2">
          {allowAiFix ? (
            <button
              type="button"
              className="flex items-center gap-2 rounded border border-red-100 bg-red-50 px-2.5 py-1.5 text-sm font-medium text-red-500 transition hover:bg-red-100"
              onClick={() => window._ziteOnFixError?.(props.error)}
            >
              <HammerIcon className="h-4 w-4" />
              Fix it for me
            </button>
          ) : null}
          <button
            type="button"
            onClick={reloadApp}
            className="flex items-center gap-2 rounded border border-gray-200 bg-gray-50 px-2.5 py-1.5 text-sm font-medium text-gray-500 transition hover:bg-gray-100"
          >
            Reload
          </button>
        </div>
      </div>
    </div>
  );
}

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <ErrorBoundary
      fallbackRender={props => <RuntimeErrorFallback error={props.error} />}
    >
      <QueryClientProvider client={queryClient}>
        <App />
      </QueryClientProvider>
    </ErrorBoundary>
  </StrictMode>,
);

