export function formatAmount(val: string): string {
  const num = parseFloat(val.replace(/,/g, ''));
  if (isNaN(num)) return '0.00';
  return num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

export function todayString(): string {
  const d = new Date();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${mm}/${dd}/${d.getFullYear()}`;
}

export const RECEIPT_W = 711;
/** Fixed receipt width; RECEIPT_H is the MINIMUM height — the receipt grows with its content. */
export const RECEIPT_H = 810;

export function mergeStyle(global: TextStyle, elem?: TextStyle): React.CSSProperties {
  const s: React.CSSProperties = {};
  const merged = { ...global, ...elem };
  if (merged.fontFamily) s.fontFamily = merged.fontFamily;
  if (merged.fontSize) s.fontSize = merged.fontSize;
  if (merged.fontWeight) s.fontWeight = merged.fontWeight;
  if (merged.fontStyle) s.fontStyle = merged.fontStyle;
  if (merged.letterSpacing !== undefined) s.letterSpacing = merged.letterSpacing;
  if (merged.lineHeight !== undefined) s.lineHeight = merged.lineHeight;
  if (merged.textAlign) s.textAlign = merged.textAlign as React.CSSProperties['textAlign'];
  return s;
}

/* ─── Line items & totals ─── */

export const parseNum = (v: string) => { const n = parseFloat(String(v ?? '').replace(/,/g, '')); return isNaN(n) ? 0 : n; };
export const money = (n: number) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
export const newLineItem = (): LineItem => ({ id: Math.random().toString(36).slice(2, 10), description: '', quantity: '1', unitPrice: '' });

export function lineAmount(i: LineItem) { return Math.round(parseNum(i.quantity) * parseNum(i.unitPrice) * 100) / 100; }

/** How a line reads on the receipt: no "(x1)" for flat fees. */
export function lineLabel(i: LineItem) {
  const q = parseNum(i.quantity);
  return q > 1 ? `${i.description} (x${Number.isInteger(q) ? q : q.toString()})` : i.description;
}

export function computeTotals(items: LineItem[]) {
  const subtotal = Math.round(items.reduce((s, i) => s + lineAmount(i), 0) * 100) / 100;
  const wht = 0, whtVat = 0;
  const less = wht + whtVat;
  const total = subtotal - less;
  return { subtotal, wht, whtVat, less, total, paidBy: 'CASH', paidTotal: total, change: 0 };
}

/** Upgrades receipts saved before multi-line support. */
export function normalizeData(d: ReceiptData): ReceiptData {
  if (d.items?.length) return d;
  return { ...d, items: [{ id: 'l1', description: d.transaction ?? '', quantity: '1', unitPrice: d.amount ?? '' }] };
}

