export function loadDesign(): BrandingSettings {
  try {
    const raw = localStorage.getItem(DESIGN_KEY);
    if (!raw) return DEFAULT_BRANDING;
    const b = JSON.parse(raw) as Partial<BrandingSettings>;
    return {
      ...DEFAULT_BRANDING, ...b,
      logo: { ...DEFAULT_LOGO, ...b.logo },
      watermark: { ...DEFAULT_WATERMARK, ...b.watermark },
      company: { ...DEFAULT_COMPANY, ...b.company },
    };
  } catch { return DEFAULT_BRANDING; }
}

export function saveDesign(b: BrandingSettings) { localStorage.setItem(DESIGN_KEY, JSON.stringify(b)); }

import { type SavedReceipt, type ReceiptData } from './types';

const STORAGE_KEY = 'converge_receipts';

export function loadReceipts(): SavedReceipt[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch { return []; }
}

export function saveReceipts(receipts: SavedReceipt[]) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(receipts));
}

export function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

export const isEmail = (s: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.trim());

export function validate(data: ReceiptData): Record<string, string> {
  const errors: Record<string, string> = {};
  if (data.customerEmail?.trim() && !isEmail(data.customerEmail)) errors.customerEmail = 'Enter a valid email address';
  if (!data.date.trim()) errors.date = 'Required';
  else if (!/^\d{2}\/\d{2}\/\d{4}$/.test(data.date)) errors.date = 'Use MM/DD/YYYY';
  if (!data.items.length) errors.items = 'Add at least one transaction';
  data.items.forEach((it, n) => {
    if (!it.description.trim()) errors[`item-${n}-description`] = 'Required';
    const q = parseFloat(it.quantity.replace(/,/g, ''));
    if (!it.quantity.trim() || isNaN(q) || q <= 0) errors[`item-${n}-quantity`] = '> 0';
    const p = parseFloat(it.unitPrice.replace(/,/g, ''));
    if (!it.unitPrice.trim() || isNaN(p) || p < 0) errors[`item-${n}-unitPrice`] = 'Invalid';
  });
  if (!data.accountName.trim()) errors.accountName = 'Required';
  if (!data.accountNumber.trim()) errors.accountNumber = 'Required';
  if (!data.address.trim()) errors.address = 'Required';
  if (!data.plan.trim()) errors.plan = 'Required';
  if (!data.generatedBy.trim()) errors.generatedBy = 'Required';
  return errors;
}

